import React, { useState } from 'react';
import { X, Star, Clock, Heart } from 'lucide-react';
import { useSticker } from '../context/StickerContext';
import { useLanguage } from '../context/LanguageContext';
import { cn } from '../utils/cn';

export default function StickerPicker({ aiId, onSelect, onClose }) {
    const { stickerPacks, getAIStickers, getFavorites, getRecentlyUsed, addRecentlyUsed, addFavorite, removeFavorite, isFavorite } = useSticker();
    const { language } = useLanguage();
    const [activeTab, setActiveTab] = useState('recent');
    const [longPressSticker, setLongPressSticker] = useState(null);

    const aiStickers = aiId ? getAIStickers(aiId) : [];
    const favorites = getFavorites();
    const recentlyUsed = getRecentlyUsed();

    const handleSelect = (sticker, packId) => {
        addRecentlyUsed(packId, sticker.id, sticker.emoji);
        onSelect?.(sticker.emoji);
    };

    const handleLongPress = (sticker, packId) => {
        setLongPressSticker({ sticker, packId });
    };

    const handleToggleFavorite = () => {
        if (!longPressSticker) return;
        const { sticker, packId } = longPressSticker;
        if (isFavorite(packId, sticker.id)) {
            removeFavorite(packId, sticker.id);
        } else {
            addFavorite(packId, sticker.id);
        }
        setLongPressSticker(null);
    };

    const tabs = [
        { id: 'recent', icon: Clock, name: '鏈€杩?, name_en: 'Recent' },
        { id: 'favorites', icon: Star, name: '鏀惰棌', name_en: 'Favorites' },
        ...(aiId ? [{ id: 'ai', icon: Heart, name: 'AI涓撳睘', name_en: 'AI Special' }] : []),
        ...stickerPacks.map(p => ({ id: p.id, emoji: p.stickers[0]?.emoji, name: p.name, name_en: p.name_en }))
    ];

    const getCurrentStickers = () => {
        if (activeTab === 'recent') return recentlyUsed.map(r => ({ ...r, packId: r.packId }));
        if (activeTab === 'favorites') return favorites.map(f => ({ ...f, packId: f.packId }));
        if (activeTab === 'ai') return aiStickers.map(s => ({ ...s, packId: 'ai' }));
        const pack = stickerPacks.find(p => p.id === activeTab);
        return pack ? pack.stickers.map(s => ({ ...s, packId: pack.id })) : [];
    };

    const currentStickers = getCurrentStickers();

    return (
        <div
            className="bg-white rounded-xl shadow-xl border border-[var(--color-border)] overflow-hidden w-80"
            onClick={e => e.stopPropagation()}
        >
            {/* Tabs */}
            <div className="flex overflow-x-auto border-b border-[var(--color-border)] px-2 py-1 hide-scrollbar">
                {tabs.map(tab => {
                    const Icon = tab.icon;
                    return (
                        <button
                            key={tab.id}
                            onClick={() => setActiveTab(tab.id)}
                            className={cn(
                                "flex-shrink-0 px-3 py-2 text-lg transition-all rounded-lg mx-0.5",
                                activeTab === tab.id
                                    ? "bg-[var(--color-primary)]/10 text-[var(--color-primary)]"
                                    : "text-[var(--color-text-muted)] hover:bg-[var(--color-bg-app)]"
                            )}
                        >
                            {Icon ? <Icon size={20} /> : tab.emoji}
                        </button>
                    );
                })}
            </div>

            {/* Stickers Grid */}
            <div className="h-48 overflow-y-auto p-2">
                {currentStickers.length === 0 ? (
                    <div className="h-full flex items-center justify-center text-[var(--color-text-muted)] text-sm">
                        {language === 'zh' ? '鏆傛棤琛ㄦ儏' : 'No stickers'}
                    </div>
                ) : (
                    <div className="grid grid-cols-6 gap-1">
                        {currentStickers.map((sticker, index) => (
                            <button
                                key={`${sticker.packId}-${sticker.id || index}`}
                                onClick={() => handleSelect(sticker, sticker.packId)}
                                onContextMenu={(e) => {
                                    e.preventDefault();
                                    handleLongPress(sticker, sticker.packId);
                                }}
                                className="w-10 h-10 flex items-center justify-center text-2xl rounded-lg hover:bg-[var(--color-bg-app)] transition-colors relative"
                            >
                                {sticker.emoji}
                                {isFavorite(sticker.packId, sticker.id) && (
                                    <Star size={8} className="absolute bottom-0.5 right-0.5 text-yellow-500 fill-yellow-500" />
                                )}
                            </button>
                        ))}
                    </div>
                )}
            </div>

            {/* Long Press Menu */}
            {longPressSticker && (
                <div className="absolute inset-0 bg-black/50 flex items-center justify-center" onClick={() => setLongPressSticker(null)}>
                    <div className="bg-white rounded-lg shadow-xl p-4 text-center" onClick={e => e.stopPropagation()}>
                        <div className="text-4xl mb-2">{longPressSticker.sticker.emoji}</div>
                        <button
                            onClick={handleToggleFavorite}
                            className="flex items-center gap-2 px-4 py-2 bg-[var(--color-bg-app)] rounded-lg hover:bg-[var(--color-primary)] hover:text-white transition-colors w-full justify-center"
                        >
                            <Star size={16} className={isFavorite(longPressSticker.packId, longPressSticker.sticker.id) ? 'fill-current' : ''} />
                            {isFavorite(longPressSticker.packId, longPressSticker.sticker.id)
                                ? (language === 'zh' ? '鍙栨秷鏀惰棌' : 'Remove')
                                : (language === 'zh' ? '娣诲姞鏀惰棌' : 'Add to favorites')
                            }
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
}

import React, { createContext, useContext, useState, useCallback, useEffect } from 'react';
import { useLocalStorage } from '../hooks/useLocalStorage';
import {
    loadIndex,
    saveIndex,
    indexDocument,
    searchDocuments,
    buildRAGContext,
    addDocumentToIndex,
    removeDocumentFromIndex
} from '../utils/ragUtils';

const DocumentContext = createContext();

export const useDocuments = () => {
    const context = useContext(DocumentContext);
    if (!context) throw new Error('useDocuments must be used within a DocumentProvider');
    return context;
};

export const DocumentProvider = ({ children }) => {
    // Document metadata storage
    const [documents, setDocuments] = useLocalStorage('chat-buddy-documents', []);

    // RAG enabled state
    const [ragEnabled, setRagEnabled] = useLocalStorage('chat-buddy-rag-enabled', true);

    // Indexed chunks (loaded from localStorage)
    const [indexedChunks, setIndexedChunks] = useState(() => loadIndex());

    // Add a new document
    const addDocument = useCallback((fileData) => {
        const newDoc = {
            id: crypto.randomUUID(),
            name: fileData.name,
            size: fileData.size,
            type: fileData.type,
            icon: fileData.icon,
            content: fileData.content,
            addedAt: new Date().toISOString()
        };

        // Add to documents list
        setDocuments(prev => [newDoc, ...prev]);

        // Index for RAG
        const updatedIndex = addDocumentToIndex(newDoc);
        setIndexedChunks(updatedIndex);

        return newDoc;
    }, [setDocuments]);

    // Remove a document
    const removeDocument = useCallback((documentId) => {
        setDocuments(prev => prev.filter(d => d.id !== documentId));

        // Remove from index
        const updatedIndex = removeDocumentFromIndex(documentId);
        setIndexedChunks(updatedIndex);
    }, [setDocuments]);

    // Search documents for RAG context
    const searchForContext = useCallback((query) => {
        if (!ragEnabled || indexedChunks.length === 0) {
            return null;
        }
        return buildRAGContext(query, indexedChunks);
    }, [ragEnabled, indexedChunks]);

    // Get document by ID
    const getDocument = useCallback((documentId) => {
        return documents.find(d => d.id === documentId);
    }, [documents]);

    // Toggle RAG
    const toggleRAG = useCallback(() => {
        setRagEnabled(prev => !prev);
    }, [setRagEnabled]);

    const value = {
        documents,
        ragEnabled,
        indexedChunks,
        addDocument,
        removeDocument,
        searchForContext,
        getDocument,
        toggleRAG,
        setRagEnabled
    };

    return (
        <DocumentContext.Provider value={value}>
            {children}
        </DocumentContext.Provider>
    );
};

import React, { createContext, useContext, useCallback } from 'react';
import { useLocalStorage } from '../hooks/useLocalStorage';

const FriendContext = createContext();

export const useFriend = () => {
    const context = useContext(FriendContext);
    if (!context) throw new Error('useFriend must be used within a FriendProvider');
    return context;
};

// Default groups
const DEFAULT_GROUPS = [
    { id: 'group-anime', name: '浜屾鍏?, name_en: 'Anime', color: '#FF6B9D', icon: '馃尭' },
    { id: 'group-study', name: '瀛︿範浼欎即', name_en: 'Study Buddies', color: '#4ECDC4', icon: '馃摎' }
];

const DEFAULT_FRIEND_DATA = {
    groups: DEFAULT_GROUPS,
    friendMeta: {}
};

export const FriendProvider = ({ children }) => {
    const [friendData, setFriendData] = useLocalStorage('chat-buddy-friend-data', DEFAULT_FRIEND_DATA);

    // Ensure groups and friendMeta exist
    const groups = friendData.groups || DEFAULT_GROUPS;
    const friendMeta = friendData.friendMeta || {};

    // ========== Group Management ==========

    // Add new group
    const addGroup = useCallback((name, name_en, color, icon) => {
        const newGroup = {
            id: `group-${Date.now()}`,
            name,
            name_en: name_en || name,
            color: color || '#808080',
            icon: icon || '馃搧'
        };
        setFriendData(prev => ({
            ...prev,
            groups: [...(prev.groups || []), newGroup]
        }));
        return newGroup.id;
    }, [setFriendData]);

    // Update group
    const updateGroup = useCallback((groupId, updates) => {
        setFriendData(prev => ({
            ...prev,
            groups: (prev.groups || []).map(g =>
                g.id === groupId ? { ...g, ...updates } : g
            )
        }));
    }, [setFriendData]);

    // Delete group (moves friends to ungrouped)
    const deleteGroup = useCallback((groupId) => {
        setFriendData(prev => {
            // Remove group
            const newGroups = (prev.groups || []).filter(g => g.id !== groupId);

            // Unassign friends from this group
            const newFriendMeta = { ...prev.friendMeta };
            Object.keys(newFriendMeta).forEach(friendId => {
                if (newFriendMeta[friendId]?.groupId === groupId) {
                    newFriendMeta[friendId] = { ...newFriendMeta[friendId], groupId: null };
                }
            });

            return {
                ...prev,
                groups: newGroups,
                friendMeta: newFriendMeta
            };
        });
    }, [setFriendData]);

    // ========== Friend Metadata ==========

    // Get friend metadata
    const getFriendMeta = useCallback((friendId) => {
        return friendMeta[friendId] || { starred: false, groupId: null, remark: '', pinned: false };
    }, [friendMeta]);

    // Toggle star status
    const toggleStar = useCallback((friendId) => {
        setFriendData(prev => {
            const currentMeta = prev.friendMeta?.[friendId] || {};
            return {
                ...prev,
                friendMeta: {
                    ...prev.friendMeta,
                    [friendId]: {
                        ...currentMeta,
                        starred: !currentMeta.starred
                    }
                }
            };
        });
    }, [setFriendData]);

    // Set remark name
    const setRemark = useCallback((friendId, remark) => {
        setFriendData(prev => {
            const currentMeta = prev.friendMeta?.[friendId] || {};
            return {
                ...prev,
                friendMeta: {
                    ...prev.friendMeta,
                    [friendId]: {
                        ...currentMeta,
                        remark: remark.slice(0, 20) // Max 20 chars
                    }
                }
            };
        });
    }, [setFriendData]);

    // Set friend group
    const setFriendGroup = useCallback((friendId, groupId) => {
        setFriendData(prev => {
            const currentMeta = prev.friendMeta?.[friendId] || {};
            return {
                ...prev,
                friendMeta: {
                    ...prev.friendMeta,
                    [friendId]: {
                        ...currentMeta,
                        groupId
                    }
                }
            };
        });
    }, [setFriendData]);

    // Toggle pinned status
    const togglePinned = useCallback((friendId) => {
        setFriendData(prev => {
            const currentMeta = prev.friendMeta?.[friendId] || {};
            return {
                ...prev,
                friendMeta: {
                    ...prev.friendMeta,
                    [friendId]: {
                        ...currentMeta,
                        pinned: !currentMeta.pinned
                    }
                }
            };
        });
    }, [setFriendData]);

    // Get display name (remark or original name)
    const getDisplayName = useCallback((friend, language = 'en') => {
        const meta = friendMeta[friend.id];
        if (meta?.remark) return meta.remark;
        return language === 'zh' ? (friend.name_zh || friend.name) : friend.name;
    }, [friendMeta]);

    // Get group for friend
    const getFriendGroup = useCallback((friendId) => {
        const meta = friendMeta[friendId];
        if (!meta?.groupId) return null;
        return groups.find(g => g.id === meta.groupId) || null;
    }, [friendMeta, groups]);

    // Get friends in a group
    const getFriendsInGroup = useCallback((groupId, allFriends) => {
        return allFriends.filter(f => {
            const meta = friendMeta[f.id];
            return meta?.groupId === groupId;
        });
    }, [friendMeta]);

    // Get starred friends
    const getStarredFriends = useCallback((allFriends) => {
        return allFriends.filter(f => friendMeta[f.id]?.starred);
    }, [friendMeta]);

    // Get ungrouped friends
    const getUngroupedFriends = useCallback((allFriends) => {
        return allFriends.filter(f => {
            const meta = friendMeta[f.id];
            return !meta?.groupId;
        });
    }, [friendMeta]);

    const value = {
        groups,
        friendMeta,
        addGroup,
        updateGroup,
        deleteGroup,
        getFriendMeta,
        toggleStar,
        setRemark,
        setFriendGroup,
        togglePinned,
        getDisplayName,
        getFriendGroup,
        getFriendsInGroup,
        getStarredFriends,
        getUngroupedFriends
    };

    return (
        <FriendContext.Provider value={value}>
            {children}
        </FriendContext.Provider>
    );
};

