    accentColor: null // custom primary color
};

export const ThemeProvider = ({ children }) => {
    const [theme, setTheme] = useLocalStorage('chat-buddy-theme', DEFAULT_THEME);

    // Apply dark mode class to document
    useEffect(() => {
        if (theme.mode === 'dark') {
            document.documentElement.classList.add('dark');
        } else {
            document.documentElement.classList.remove('dark');
        }
    }, [theme.mode]);

    // Apply custom accent color
    useEffect(() => {
        if (theme.accentColor) {
            document.documentElement.style.setProperty('--color-primary', theme.accentColor);
        } else {
            document.documentElement.style.removeProperty('--color-primary');
        }
    }, [theme.accentColor]);

    // ========== Theme Mode ==========

    const toggleDarkMode = useCallback(() => {
        setTheme(prev => ({
            ...prev,
            mode: prev.mode === 'dark' ? 'light' : 'dark'
        }));
    }, [setTheme]);

    const setDarkMode = useCallback((isDark) => {
        setTheme(prev => ({ ...prev, mode: isDark ? 'dark' : 'light' }));
    }, [setTheme]);

    // ========== Chat Background ==========

    const setChatBackground = useCallback((backgroundId) => {
        setTheme(prev => ({ ...prev, chatBackground: backgroundId, customBackground: null }));
    }, [setTheme]);

    const setCustomBackground = useCallback((imageBase64) => {
        setTheme(prev => ({ ...prev, chatBackground: 'custom', customBackground: imageBase64 }));
    }, [setTheme]);

    const getChatBackgroundStyle = useCallback(() => {
        if (theme.chatBackground === 'custom' && theme.customBackground) {
            return {
                backgroundImage: `url(${theme.customBackground})`,
                backgroundSize: 'cover',
                backgroundPosition: 'center'
            };
        }

        const bg = CHAT_BACKGROUNDS.find(b => b.id === theme.chatBackground);
        if (!bg || !bg.value) return {};

        return {
            background: bg.value,
            backgroundSize: bg.bgSize || 'cover'
        };
    }, [theme.chatBackground, theme.customBackground]);

    // ========== Accent Color ==========

    const setAccentColor = useCallback((color) => {
        setTheme(prev => ({ ...prev, accentColor: color }));
    }, [setTheme]);

    const resetAccentColor = useCallback(() => {
        setTheme(prev => ({ ...prev, accentColor: null }));
    }, [setTheme]);

    const value = {
        // Current theme
        theme,
        isDarkMode: theme.mode === 'dark',

        // Theme mode
        toggleDarkMode,
        setDarkMode,

        // Backgrounds
        chatBackgrounds: CHAT_BACKGROUNDS,
        setChatBackground,
        setCustomBackground,
        getChatBackgroundStyle,

        // Accent color
        setAccentColor,
        resetAccentColor
    };

    return (
        <ThemeContext.Provider value={value}>
            {children}
        </ThemeContext.Provider>
    );
};

import React, { createContext, useContext, useCallback } from 'react';
import { useLocalStorage } from '../hooks/useLocalStorage';

const UserContext = createContext();

export const useUser = () => {
    const context = useContext(UserContext);
    if (!context) throw new Error('useUser must be used within a UserProvider');
    return context;
};

const DEFAULT_PROFILE = {
    id: 'user-me',
    nickname: '',
    avatar: null,
    signature: '',
    createdAt: new Date().toISOString()
};

export const UserProvider = ({ children }) => {
    const [userProfile, setUserProfile] = useLocalStorage('chat-buddy-user-profile', DEFAULT_PROFILE);

    // Update nickname
    const updateNickname = useCallback((nickname) => {
        setUserProfile(prev => ({
            ...prev,
            nickname: nickname.trim().slice(0, 20) // Max 20 chars
        }));
    }, [setUserProfile]);

    // Update avatar (path or base64 data URL)
    const updateAvatar = useCallback((avatar) => {
        setUserProfile(prev => ({
            ...prev,
            avatar
        }));
    }, [setUserProfile]);

    // Update signature/status
    const updateSignature = useCallback((signature) => {
        setUserProfile(prev => ({
            ...prev,
            signature: signature.slice(0, 100) // Max 100 chars
        }));
    }, [setUserProfile]);

    // Reset profile to defaults
    const resetProfile = useCallback(() => {
        setUserProfile({
            ...DEFAULT_PROFILE,
            createdAt: new Date().toISOString()
        });
    }, [setUserProfile]);

    // Get display name (nickname or default)
    const getDisplayName = useCallback((language = 'en') => {
        if (userProfile.nickname) return userProfile.nickname;
        return language === 'zh' ? '浣? : 'You';
    }, [userProfile.nickname]);

    const value = {
        userProfile,
        updateNickname,
        updateAvatar,
        updateSignature,
        resetProfile,
        getDisplayName
    };

    return (
        <UserContext.Provider value={value}>
            {children}
        </UserContext.Provider>
    );
};

import { cleanMessageContent, calculateTypingDelay, getRandomDelay, compressContext } from '../../features/chat/services/chatService';
import { executeTool } from '../../features/chat/services/toolService';
import { callAI } from '../../features/chat/services/chatService';

/**
 * Domain Layer: AI Pipeline
 * Manages the "Mental Model" of the AI:
 * 1. Context Preparation (Compression, Summary)
 * 2. ReAct Loop (Thinking -> Tool -> Result -> Thinking)
 * 3. Response Generation (Typing delays, Multi-message parsing)
 */
export class AIPipeline {
    constructor(callbacks) {
        this.callbacks = callbacks || {};
        // callbacks: { onTyping, onMessage, onLog }
    }

    log(msg, data) {
        if (this.callbacks.onLog) this.callbacks.onLog(msg, data);
        else console.log(msg, data || '');
    }

    /**
     * Main entry point to trigger AI response
     */
    async processTurn(chat, personas, triggerAI) {
        const ai = personas.find(p => p.id === triggerAI.id);
        if (!ai) return;

        const chatId = chat.id;

        // 1. Calculate Delays
        const readDelay = getRandomDelay(ai.readDelay || { min: 500, max: 2000 });
        const thinkingDelay = getRandomDelay(ai.responseDelay || { min: 1000, max: 2000 });

        await this._wait(readDelay);

        // 2. Start "Typing"
        this.callbacks.onTyping?.(chatId, ai.id, true);

        await this._wait(thinkingDelay);

        try {
            // 3. Prepare Context
            const { compressed, summary, recentMessages } = compressContext(chat.messages, personas);
            const messagesToProcess = compressed ? recentMessages : chat.messages;
            const history = this._prepareHistory(messagesToProcess, personas, compressed, summary, chat.polls);

            // Allow AI to see the latest user message specifically? 
            // The history builder handles this.

            // 4. Generate System Prompt
            const isGroup = chat.participants.length > 2;
            const perms = chat.permissions || { allowReactions: true };
            const systemPrompt = this._generateSystemPrompt(ai, isGroup, perms);

            // 5. Run ReAct Loop
            await this._runReActLoop(chatId, ai, systemPrompt, history);

        } catch (error) {
            console.error('[AIPipeline] Error:', error);
            this.callbacks.onTyping?.(chatId, ai.id, false);
        }
    }

    async _runReActLoop(chatId, ai, systemPrompt, initialHistory, depth = 0) {
        if (depth > 3) {
            this.log('[AIPipeline] Max depth reached');
            this.callbacks.onTyping?.(chatId, ai.id, false);
            return;
        }

        // Call LLM
        const requestMessages = [{ role: 'system', content: systemPrompt }, ...initialHistory];
        const response = await callAI(requestMessages, {
            systemPrompt: ai.systemPrompt,
            agentId: ai.id,
            maxTokens: depth > 0 ? 500 : undefined
        });

        if (!response) {
            this.callbacks.onTyping?.(chatId, ai.id, false);
            return;
        }

        // Check for Tool Calls
        const toolMatch = response.match(/\[TOOL_CALL:\s*(\w+)\s*(\{.*?\})\s*\]/);

        if (toolMatch) {
            // --- Tool Execution Path ---
            const [fullMatch, toolName, argsStr] = toolMatch;
            this.log(`[Tool Call] ${toolName}`, argsStr);

            try {
                const args = JSON.parse(argsStr);
                const toolOutput = await executeTool(toolName, args);

                // Recursive Call
                const newHistory = [
                    ...initialHistory,
                    { role: 'assistant', content: response },
                    { role: 'user', content: `[TOOL_RESULT for ${toolName}]\n${toolOutput}\n\n[Please continue based on this result]` }
                ];

                await this._runReActLoop(chatId, ai, systemPrompt, newHistory, depth + 1);

            } catch (e) {
                this.log('[Tool Error]', e);
                const newHistory = [
                    ...initialHistory,
                    { role: 'assistant', content: response },
                    { role: 'user', content: `[TOOL_ERROR]: ${e.message}` }
                ];
                await this._runReActLoop(chatId, ai, systemPrompt, newHistory, depth + 1);
            }

        } else {
            // --- Final Response Path ---
            await this._handleFinalResponse(chatId, ai, response);
        }
    }

    async _handleFinalResponse(chatId, ai, response) {
        if (!response) {
            this.callbacks.onTyping?.(chatId, ai.id, false);
            return;
        }

        if (response.includes('[SILENCE]')) {
            this.callbacks.onTyping?.(chatId, ai.id, false);
            return;
        }

        // Parse SCHEDULE
        const scheduleMatch = response.match(/\[SCHEDULE:(\d+)\]/);
        let cleanResponse = response;
        if (scheduleMatch) {
            const minutes = parseInt(scheduleMatch[1]);
            cleanResponse = response.replace(scheduleMatch[0], '').trim();
            this.callbacks.onSchedule?.(chatId, ai, minutes);
        }

        // Parse MULTI
        const multiMatch = cleanResponse.match(/\[(?:MULTI|Multi|multi):(.+?)\]/i);

        if (multiMatch) {
            const parts = multiMatch[1].split('|').map(m => m.trim()).filter(Boolean);
            cleanResponse = cleanResponse.replace(multiMatch[0], '').trim();

            // Send parts sequentially
            for (let i = 0; i < parts.length; i++) {
                if (i > 0) {
                    this.callbacks.onTyping?.(chatId, ai.id, true);
                    await this._wait(800 + Math.random() * 1000);
                }
                await this._simulateTypingAndSend(chatId, ai, parts[i]);
            }

            // Send remainder if any
            if (cleanResponse) {
                this.callbacks.onTyping?.(chatId, ai.id, true);
                await this._wait(1000);
                await this._simulateTypingAndSend(chatId, ai, cleanResponse);
            }
        } else {
            // Standard single message
            await this._simulateTypingAndSend(chatId, ai, cleanResponse);
        }

        // Done
        this.callbacks.onTyping?.(chatId, ai.id, false);
    }

    async _simulateTypingAndSend(chatId, ai, content) {
        const delay = calculateTypingDelay(content.length, ai.typingSpeed || 'normal');
        await this._wait(delay);
        this.callbacks.onMessage?.(chatId, content, ai.id);
    }

    _wait(ms) {
        return new Promise(resolve => setTimeout(resolve, ms));
    }

    // --- Helpers Copied/Refactored from Context ---
    // In a future step, these could be extracted to a pure utility class

    _prepareHistory(messages, personas, compressed, summary, polls) {
        const rawHistory = messages.slice(-12).map(m => {
            const isUser = m.senderId === 'user-me';
            const sender = isUser ? 'User' : personas.find(p => p.id === m.senderId)?.name || 'Unknown';

            let content = m.content;
            if (content.startsWith('[POLL:') && polls) {
                const pollMatch = content.match(/\[POLL:(.+?)\]/);
                if (pollMatch) {
                    const poll = polls.find(p => p.id === pollMatch[1]);
                    if (poll) {
                        content = `[System: Poll created: "${poll.question}". Options: ${poll.options.map((o, i) => `${i + 1}. ${o.text}`).join(', ')}. Please vote.]`;
                    }
                }
            }

            return {
                role: isUser ? 'user' : 'assistant',
                content: `${sender}: ${content}`
            };
        });

        // Merge consecutive roles
        const history = [];
        for (const msg of rawHistory) {
            if (history.length > 0 && history[history.length - 1].role === msg.role) {
                history[history.length - 1].content += '\n' + msg.content;
            } else {
                history.push({ ...msg });
            }
        }

        if (history.length > 0 && history[0].role === 'assistant') {
            history.unshift({ role: 'user', content: compressed ? summary : '[Previous chat context]' });
        }

        return history;
    }

    _generateSystemPrompt(ai, isGroup, perms) {
        // Reuse existing prompt generation logic
        // For brevity in this refactor, condensing it. 
        // Ideally imported from a PromptBuilder domain service.
        const base = `You are ${ai.name}.\nPersonality: ${ai.personality}\nStyle: ${ai.style}`;
        const tools = `
AVAILABLE TOOLS:
1. SEND MESSAGE - Normal response
2. STAY SILENT - [SILENCE]
3. MULTI MESSAGE - [MULTI:msg1|msg2]
4. SCHEDULE - [SCHEDULE:mins]
${ai.agentType === 'task-specialist' ? this._getSpecialistTools(ai) : ''}
`;
        return `${base}\n${tools}\nRULES: Keep it short. Respond to mentions.`;
    }

    _getSpecialistTools(ai) {
        return (ai.tools || []).map(t => `- [TOOL_CALL: ${t.name} ...arguments]`).join('\n');
    }
}

import { storage } from '../../services/storage/StorageService';
import { AIPipeline } from './AIPipeline';
import { cleanMessageContent } from '../../features/chat/services/chatService';

/**
 * Domain Layer: Chat Engine
 * The central nervous system for Chat Buddy.
 * Manages:
 * - Persistence (via StorageService)
 * - State mutations (Business Logic)
 * - AI Orchestration (via AIPipeline)
 */
export class ChatEngine {
    constructor() {
        this.storageKey = 'chat-buddy-chats';
        this.chats = [];
        this.currentUserId = 'user-me';
        this.personas = []; // Need to be injected or loaded
        this.listeners = new Set();

        // Ephemeral state
        this.typingIndicators = {}; // { chatId: [aiId, ...] }

        // Sub-systems
        this.aiPipeline = new AIPipeline({
            onTyping: this._handleAITyping.bind(this),
            onMessage: this._handleAIMessage.bind(this),
            onSchedule: this._handleAISchedule.bind(this),
            onLog: (msg, data) => console.log(`[ChatEngine] ${msg}`, data)
        });
    }

    /**
     * Initialize engine with data
     */
    init(personas) {
        this.personas = personas;
        this.chats = storage.get(this.storageKey, []);
        console.log('[ChatEngine] Initialized with', this.chats.length, 'chats');
        this._notify();
    }

    /**
     * Subscribe to state changes
     */
    subscribe(callback) {
        this.listeners.add(callback);
        return () => this.listeners.delete(callback);
    }

    _notify() {
        // Emit a snapshot of the current state
        const state = {
            chats: this.chats,
            typingIndicators: { ...this.typingIndicators }
        };
        this.listeners.forEach(cb => cb(state));
    }

    save() {
        storage.set(this.storageKey, this.chats);
        this._notify();
    }

    // =========================================================================
    // Business Logic: Message Actions
    // =========================================================================

    sendMessage(chatId, content, senderId = 'user-me', quotedMessageId = null) {
        const cleaned = cleanMessageContent(content);
        if (!cleaned) return;

        const chatIndex = this.chats.findIndex(c => c.id === chatId);
        if (chatIndex === -1) return;

        const newMessage = {
            id: crypto.randomUUID(),
            senderId,
            content: cleaned,
            timestamp: new Date().toISOString(),
            status: 'sent',
            quotedMessageId,
            readBy: []
        };

        // Mutation
        const updatedChat = { ...this.chats[chatIndex] };
        updatedChat.messages = [...updatedChat.messages, newMessage];
        updatedChat.lastMessage = newMessage;
        updatedChat.updatedAt = newMessage.timestamp;

        this.chats[chatIndex] = updatedChat;
        this.save();

        // Trigger AI if user sent message
        if (senderId === 'user-me') {
            this._triggerAIResponse(updatedChat);
        }
    }

    deleteMessage(chatId, messageId) {
        const chatIndex = this.chats.findIndex(c => c.id === chatId);
        if (chatIndex === -1) return;

        const chat = this.chats[chatIndex];
        const updatedMessages = chat.messages.filter(m => m.id !== messageId);

        this.chats[chatIndex] = {
            ...chat,
            messages: updatedMessages
        };
        this.save();
    }

    createChat(name, participantIds, avatar = null) {
        const newChat = {
            id: crypto.randomUUID(),
            name,
            avatar,
            participants: ['user-me', ...participantIds],
            admins: ['user-me'],
            messages: [],
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString(),
            theme: 'default',
            settings: {
                muteValues: {}
            },
            polls: []
        };

        this.chats = [newChat, ...this.chats];
        this.save();
        return newChat.id;
    }

    // =========================================================================
    // Extended Actions (Legacy Parity)
    // =========================================================================

    updateChat(chatId, updates) {
        const chatIndex = this.chats.findIndex(c => c.id === chatId);
        if (chatIndex === -1) return;

        this.chats[chatIndex] = { ...this.chats[chatIndex], ...updates };
        this.save();
    }

    pinMessage(chatId, messageId, isPinned) {
        const chatIndex = this.chats.findIndex(c => c.id === chatId);
        if (chatIndex === -1) return;

        const chat = this.chats[chatIndex];
        const pinnedMessages = chat.pinnedMessages || [];

        let newPinned;
        if (isPinned) {
            if (!pinnedMessages.includes(messageId)) {
                newPinned = [...pinnedMessages, messageId];
            } else {
                return;
            }
        } else {
            newPinned = pinnedMessages.filter(id => id !== messageId);
        }

        this.chats[chatIndex] = { ...chat, pinnedMessages: newPinned };
        this.save();
    }

    votePoll(chatId, pollId, optionId) {
        // Implement poll voting logic if needed widely
        // For now, simple mutation
        const chatIndex = this.chats.findIndex(c => c.id === chatId);
        if (chatIndex === -1) return;
        const chat = this.chats[chatIndex];

        const polls = chat.polls || [];
        const pollIndex = polls.findIndex(p => p.id === pollId);
        if (pollIndex === -1) return;

        const poll = { ...polls[pollIndex] };
        // Assuming poll structure: { options: [{id, votes:[]}] }
        // This logic is simplified; real logic might be complex. 
        // Adapting from typical poll logic:
        const updatedOptions = poll.options.map(opt => {
            if (opt.id === optionId) {
                // Toggle vote or add? Assuming add for now.
                // Simple version: increment count or add userId
                return { ...opt, votes: [...(opt.votes || []), 'user-me'] };
            }
            return opt;
        });

        poll.options = updatedOptions;

        const newPolls = [...polls];
        newPolls[pollIndex] = poll;

        this.chats[chatIndex] = { ...chat, polls: newPolls };
        this.save();
    }

    // =========================================================================
    // AI Orchestration
    // =========================================================================

    _handleAITyping(chatId, aiId, isTyping) {
        const current = this.typingIndicators[chatId] || [];

        if (isTyping) {
            if (!current.includes(aiId)) {
                this.typingIndicators[chatId] = [...current, aiId];
            }
        } else {
            this.typingIndicators[chatId] = current.filter(id => id !== aiId);
            if (this.typingIndicators[chatId].length === 0) {
                delete this.typingIndicators[chatId];
            }
        }
        this._notify(); // Ephemeral update, no save
    }

    _handleAIMessage(chatId, content, aiId) {
        // AI sends message -> Reuse internal logic
        this.sendMessage(chatId, content, aiId);
    }

    _handleAISchedule(chatId, ai, minutes) {
        console.log(`[ChatEngine] Scheduling proactive msg for ${ai.name} in ${minutes}m`);
        // TODO: Implement robust scheduling via setTimeout or a Scheduler Service
        // For standard "Refactor Phase 2", we can keep it simple:
        setTimeout(() => {
            const chat = this.chats.find(c => c.id === chatId);
            if (chat) {
                // Determine if we should still send (check last msg time)
                const lastMsg = chat.messages[chat.messages.length - 1];
                const timeDiff = Date.now() - new Date(lastMsg.timestamp).getTime();
                if (timeDiff > minutes * 60 * 1000 * 0.8) {
                    this.aiPipeline.processTurn(chat, this.personas, ai);
                }
            }
        }, minutes * 60 * 1000);
    }

    _triggerAIResponse(chat) {
        // Logic to determine WHICH AI should respond
        const candidates = chat.participants
            .filter(id => id !== 'user-me')
            .map(id => this.personas.find(p => p.id === id))
            .filter(Boolean);

        // Simple loop similar to original Context
        // To prevent double-responses, we can use a queue or just stagger them
        candidates.forEach((ai, index) => {
            // Check if AI was mentioned or if it's 1-on-1
            const isMentioned = chat.lastMessage.content.includes(`@${ai.name}`);
            const isDirect = chat.participants.length === 2;

            // Should respond?
            if (isDirect || isMentioned || Math.random() > 0.3) {
                this.aiPipeline.processTurn(chat, this.personas, ai);
            }
        });
    }
}

