                    <ArrowLeft size={22} />
                </button>
                <h1 className="text-[17px] font-medium text-[var(--color-text-main)]">{t('chat_info_title')}</h1>
            </div>

            {/* Members Grid */}
            <div className="bg-white p-4 mb-2">
                <div className="flex flex-wrap gap-4">
                    {aiParticipants.map(pid => {
                        const persona = personas.find(p => p.id === pid);
                        if (!persona) return null;
                        const pName = language === 'zh' ? (persona.name_zh || persona.name) : persona.name;
                        return (
                            <div key={pid} className="flex flex-col items-center w-14 cursor-pointer" onClick={() => {
                                const currentNickname = chat.nicknames?.[pid] || pName;
                                const newNickname = window.prompt(language === 'zh' ? '璁剧疆缇ゆ樀绉? : 'Set group nickname', currentNickname);
                                if (newNickname !== null) {
                                    const currentNicknames = chat.nicknames || {};
                                    updateChat(id, { nicknames: { ...currentNicknames, [pid]: newNickname } });
                                }
                            }}>
                                <div className="w-12 h-12 rounded-[4px] overflow-hidden bg-[#E0E0E0] mb-1 relative">
                                    <img src={persona.avatar} alt={pName} className="w-full h-full object-cover" />
                                </div>
                                <span className="text-[12px] text-[var(--color-text-main)] text-center truncate w-full">
                                    {chat.nicknames?.[pid] || pName}
                                </span>
                            </div>
                        );
                    })}
                    {/* Add button */}
                    <div className="flex flex-col items-center w-14">
                        <div className="w-12 h-12 rounded-[4px] border-2 border-dashed border-[#C7C7CC] flex items-center justify-center mb-1 cursor-pointer">
                            <span className="text-[24px] text-[#C7C7CC]">+</span>
                        </div>
                    </div>
                </div>
            </div>

            {/* Group Name */}
            <div className="bg-white mb-2">
                <div className="flex items-center px-4 py-3 border-b border-[var(--color-border-light)]">
                    <span className="text-[16px] text-[var(--color-text-main)] mr-4">{t('group_name_label')}</span>
                    <input
                        type="text"
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                        onBlur={handleSaveName}
                        className="flex-1 text-right text-[16px] text-[var(--color-text-muted)] focus:outline-none"
                    />
                    <ChevronRight size={20} className="text-[#C7C7CC] ml-1" />
                </div>
            </div>

            {/* Group Features */}
            <div className="bg-white mb-2">
                <div
                    className="flex items-center px-4 py-3 border-b border-[var(--color-border-light)] cursor-pointer active:bg-gray-50"
                    onClick={() => setShowAnnouncement(true)}
                >
                    <Megaphone size={20} className="text-[var(--color-primary)] mr-3" />
                    <span className="flex-1 text-[16px] text-[var(--color-text-main)]">
                        {language === 'zh' ? '缇ゅ叕鍛? : 'Group Announcement'}
                    </span>
                    {chat.announcement && (
                        <span className="text-xs text-[var(--color-text-muted)] mr-2 truncate max-w-[100px]">
                            {chat.announcement.content}
                        </span>
                    )}
                    <ChevronRight size={20} className="text-[#C7C7CC]" />
                </div>
                <div
                    className="flex items-center px-4 py-3 border-b border-[var(--color-border-light)] cursor-pointer active:bg-gray-50"
                    onClick={() => setShowPoll(true)}
                >
                    <BarChart3 size={20} className="text-[var(--color-primary)] mr-3" />
                    <span className="flex-1 text-[16px] text-[var(--color-text-main)]">
                        {language === 'zh' ? '缇ゆ姇绁? : 'Group Poll'}
                    </span>
                    <ChevronRight size={20} className="text-[#C7C7CC]" />
                </div>
            </div>

            {/* Export */}
            <div className="bg-white mb-2">
                <div
                    className="flex items-center px-4 py-3 border-b border-[var(--color-border-light)] cursor-pointer active:bg-gray-50"
                    onClick={handleExportChat}
                >
                    <Download size={20} className="text-[var(--color-text-main)] mr-3" />
                    <span className="flex-1 text-[16px] text-[var(--color-text-main)]">
                        {language === 'zh' ? '瀵煎嚭鑱婂ぉ璁板綍' : 'Export Chat History'}
                    </span>
                    <ChevronRight size={20} className="text-[#C7C7CC]" />
                </div>
            </div>

            {/* AI Permissions */}
            <div className="bg-white mb-2">
                <ToggleItem
                    label={t('allow_reactions')}
                    checked={permissions.allowReactions}
                    onChange={(v) => togglePermission('allowReactions', v)}
                />
                <ToggleItem
                    label={t('allow_images')}
                    checked={permissions.allowImages}
                    onChange={(v) => togglePermission('allowImages', v)}
                />
            </div>

            {/* Group Admin Settings */}
            <div className="bg-white mb-2">
                <ToggleItem
                    label={language === 'zh' ? '娑堟伅鍏嶆墦鎵? : 'Mute Notifications'}
                    checked={chat.isMuted || false}
                    onChange={(v) => updateChat(id, { isMuted: v })}
                />
                <ToggleItem
                    label={language === 'zh' ? '浠呯鐞嗗憳鍙彂瑷€' : 'Admin Only Chat'}
                    checked={chat.adminOnly || false}
                    onChange={(v) => updateChat(id, { adminOnly: v })}
                />
            </div>

            {/* Danger Zone */}
            <div className="bg-white mb-6">
                <button
                    onClick={() => {
                        if (window.confirm(language === 'zh' ? '纭畾瑕佹竻绌鸿亰澶╄褰曞悧锛? : 'Are you sure you want to clear chat history?')) {
                            clearChatMessages(id);
                            alert(language === 'zh' ? '鑱婂ぉ璁板綍宸叉竻绌? : 'Chat history cleared');
                        }
                    }}
                    className="w-full px-4 py-3 text-center text-[var(--color-text-main)] text-[16px] border-b border-[var(--color-border-light)]"
                >
                    {language === 'zh' ? '娓呯┖鑱婂ぉ璁板綍' : 'Clear Chat History'}
                </button>
                <button
                    onClick={handleDeleteChat}
                    className="w-full px-4 py-3 text-center text-[#FA5151] text-[16px]"
                >
                    {t('delete_chat')}
                </button>
            </div>

            {/* Modals */}
            {
                showAnnouncement && (
                    <GroupAnnouncement
                        announcement={chat.announcement}
                        isAdmin={true} // Assuming current user is admin for now
                        onClose={() => setShowAnnouncement(false)}
                        onSave={handleSaveAnnouncement}
                        onDelete={handleDeleteAnnouncement}
                    />
                )
            }

            {
                showPoll && (
                    <GroupPoll
                        chatId={id}
                        onClose={() => setShowPoll(false)}
                        onCreatePoll={handleCreatePoll}
                    />
                )
            }
        </div >
    );
}

function ToggleItem({ label, checked, onChange }) {
    return (
        <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--color-border-light)]">
            <span className="text-[16px] text-[var(--color-text-main)]">{label}</span>
            <button
                onClick={() => onChange(!checked)}
                className={cn(
                    "w-12 h-7 rounded-full transition-colors relative",
                    checked ? "bg-[var(--color-primary)]" : "bg-[#E5E5EA]"
                )}
            >
                <div
                    className={cn(
                        "absolute top-0.5 w-6 h-6 rounded-full bg-white shadow transition-transform",
                        checked ? "translate-x-5" : "translate-x-0.5"
                    )}
                />
            </button>
        </div>
    );
}

import React, { useState } from 'react';
import { X, Send, Search, Check } from 'lucide-react';
import { useChat } from '../context/ChatContext';
import { useFriend } from '../../../context/FriendContext';
import { useLanguage } from '../../../context/LanguageContext';
import { cn } from '../../../utils/cn';

export default function ForwardModal({ message, onClose, onForward }) {
    const { chats, personas } = useChat();
    const { getDisplayName } = useFriend();
    const { t, language } = useLanguage();
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedChats, setSelectedChats] = useState([]);

    // Filter chats based on search
    const filteredChats = chats.filter(chat => {
        const chatName = chat.name || '';
        const matches = chatName.toLowerCase().includes(searchTerm.toLowerCase());

        // Also check participant names
        const participantMatches = chat.participants.some(pId => {
            if (pId === 'user-me') return false;
            const persona = personas.find(p => p.id === pId);
            if (!persona) return false;
            const name = language === 'zh' ? (persona.name_zh || persona.name) : persona.name;
            return name.toLowerCase().includes(searchTerm.toLowerCase());
        });

        return matches || participantMatches;
    });

    const toggleChat = (chatId) => {
        setSelectedChats(prev =>
            prev.includes(chatId)
                ? prev.filter(id => id !== chatId)
                : [...prev, chatId]
        );
    };

    const handleForward = () => {
        if (selectedChats.length === 0) return;
        onForward?.(message, selectedChats);
        onClose?.();
    };

    const getChatName = (chat) => {
        if (chat.name) return chat.name;
        const otherId = chat.participants.find(p => p !== 'user-me');
        const persona = personas.find(p => p.id === otherId);
        return persona ? (language === 'zh' ? persona.name_zh || persona.name : persona.name) : 'Unknown';
    };

    const getChatAvatar = (chat) => {
        const otherId = chat.participants.find(p => p !== 'user-me');
        const persona = personas.find(p => p.id === otherId);
        return persona?.avatar || null;
    };

    if (!message) return null;

    return (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4" onClick={onClose}>
            <div
                className="bg-white rounded-xl w-full max-w-md max-h-[70vh] flex flex-col overflow-hidden animate-scale-in"
                onClick={e => e.stopPropagation()}
            >
                {/* Header */}
                <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--color-border)]">
                    <button onClick={onClose} className="text-[var(--color-text-muted)]">
                        <X size={24} />
                    </button>
                    <h3 className="font-medium text-[17px]">{t('forward_to') || 'Forward to'}</h3>
                    <button
                        onClick={handleForward}
                        disabled={selectedChats.length === 0}
                        className={cn(
                            "p-2 rounded-full transition-colors",
                            selectedChats.length > 0
                                ? "text-[var(--color-primary)]"
                                : "text-[var(--color-text-light)]"
                        )}
                    >
                        <Send size={20} />
                    </button>
                </div>

                {/* Message Preview */}
                <div className="px-4 py-2 bg-[var(--color-bg-app)] border-b border-[var(--color-border)]">
                    <p className="text-sm text-[var(--color-text-muted)]">
                        {t('forwarding_message') || 'To forward:'}
                    </p>
                    <p className="text-sm truncate mt-1">
                        {message.content?.slice(0, 50)}{message.content?.length > 50 ? '...' : ''}
                    </p>
                </div>

                {/* Search */}
                <div className="px-4 py-2 border-b border-[var(--color-border)]">
                    <div className="relative">
                        <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)]" />
                        <input
                            type="text"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            placeholder={t('search_chats') || 'Search chats...'}
                            className="w-full pl-10 pr-4 py-2 bg-[var(--color-bg-app)] rounded-lg text-sm outline-none"
                        />
                    </div>
                </div>

                {/* Chat List */}
                <div className="flex-1 overflow-y-auto">
                    {filteredChats.length === 0 ? (
                        <div className="p-8 text-center text-[var(--color-text-muted)]">
                            {t('no_chats_found') || 'No chats found'}
                        </div>
                    ) : (
                        filteredChats.map(chat => (
                            <button
                                key={chat.id}
                                onClick={() => toggleChat(chat.id)}
                                className="w-full px-4 py-3 flex items-center gap-3 hover:bg-[var(--color-bg-app)] transition-colors"
                            >
                                {/* Avatar */}
                                <div className="w-10 h-10 rounded-full overflow-hidden bg-[var(--color-primary)] flex-shrink-0">
                                    {getChatAvatar(chat) ? (
                                        <img src={getChatAvatar(chat)} alt="" className="w-full h-full object-cover" />
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center text-white font-medium">
                                            {getChatName(chat).charAt(0)}
                                        </div>
                                    )}
                                </div>

                                {/* Name */}
                                <div className="flex-1 text-left">
                                    <p className="font-medium text-[var(--color-text-main)]">
                                        {getChatName(chat)}
                                    </p>
                                    {chat.participants.length > 2 && (
                                        <p className="text-xs text-[var(--color-text-muted)]">
                                            {chat.participants.length} {t('members') || 'members'}
                                        </p>
                                    )}
                                </div>

                                {/* Checkbox */}
                                <div className={cn(
                                    "w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all",
                                    selectedChats.includes(chat.id)
                                        ? "bg-[var(--color-primary)] border-[var(--color-primary)]"
                                        : "border-[var(--color-text-muted)]"
                                )}>
                                    {selectedChats.includes(chat.id) && (
                                        <Check size={14} className="text-white" />
                                    )}
                                </div>
                            </button>
                        ))
                    )}
                </div>

                {/* Footer */}
                {selectedChats.length > 0 && (
                    <div className="px-4 py-3 border-t border-[var(--color-border)] bg-[var(--color-bg-app)]">
                        <p className="text-sm text-[var(--color-text-muted)]">
                            {selectedChats.length} {t('selected') || 'selected'}
                        </p>
                    </div>
                )}
            </div>
        </div>
    );
}

import React, { useState, useCallback } from 'react';
import { X, Gift, Heart, Star, Diamond, Crown, Flower2 } from 'lucide-react';
import { useSocial } from '../../../context/SocialContext';
import { useLanguage } from '../../../context/LanguageContext';
import { cn } from '../../../utils/cn';

export default function GiftPanel({ recipientId, recipientName, onClose, onGiftSent }) {
    const { gifts, sendGift, points, getIntimacy, getIntimacyLevel } = useSocial();
    const { t, language } = useLanguage();
    const [selectedGift, setSelectedGift] = useState(null);
    const [sending, setSending] = useState(false);
    const [result, setResult] = useState(null);

    const intimacy = getIntimacy(recipientId);
    const intimacyLevel = getIntimacyLevel(recipientId);

    const handleSend = useCallback(async () => {
        if (!selectedGift) return;
        setSending(true);

        const sendResult = sendGift(recipientId, selectedGift.id);

        setTimeout(() => {
            setSending(false);
            setResult(sendResult);

            if (sendResult.success) {
                onGiftSent?.(selectedGift, sendResult.newIntimacy);
                setTimeout(() => {
                    setSelectedGift(null);
                    setResult(null);
                }, 1500);
            }
        }, 800);
    }, [selectedGift, recipientId, sendGift, onGiftSent]);

    const getGiftIcon = (giftId) => {
        const icons = {
            flower: Flower2,
            cake: Gift,
            heart: Heart,
            star: Star,
            diamond: Diamond,
            crown: Crown
        };
        return icons[giftId] || Gift;
    };

    return (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-end justify-center" onClick={onClose}>
            <div
                className="bg-white rounded-t-2xl w-full max-w-lg animate-slide-up"
                onClick={e => e.stopPropagation()}
            >
                {/* Header */}
                <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--color-border)]">
                    <div>
                        <h3 className="font-medium text-[17px]">
                            {language === 'zh' ? `閫佺ぜ鐗╃粰 ${recipientName}` : `Send gift to ${recipientName}`}
                        </h3>
                        <p className="text-sm text-[var(--color-text-muted)]">
                            {language === 'zh' ? '绉垎' : 'Points'}: {points}
                        </p>
                    </div>
                    <button onClick={onClose} className="text-[var(--color-text-muted)]">
                        <X size={24} />
                    </button>
                </div>

                {/* Intimacy Bar */}
                <div className="px-4 py-3 bg-[var(--color-bg-app)]">
                    <div className="flex items-center justify-between mb-2">
                        <span className="text-sm font-medium" style={{ color: intimacyLevel.color }}>
                            {language === 'zh' ? intimacyLevel.name : intimacyLevel.name_en}
                        </span>
                        <span className="text-sm text-[var(--color-text-muted)]">
                            {intimacy}/100
                        </span>
                    </div>
                    <div className="h-2 bg-gray-200 rounded-full overflow-hidden">
                        <div
                            className="h-full transition-all duration-500"
                            style={{
                                width: `${intimacy}%`,
                                backgroundColor: intimacyLevel.color
                            }}
                        />
                    </div>
                </div>

                {/* Gift Grid */}
                <div className="p-4 grid grid-cols-3 gap-3">
                    {gifts.map(gift => {
                        const Icon = getGiftIcon(gift.id);
                        const canAfford = points >= gift.cost;
                        const isSelected = selectedGift?.id === gift.id;

                        return (
                            <button
                                key={gift.id}
                                onClick={() => canAfford && setSelectedGift(gift)}
                                disabled={!canAfford}
                                className={cn(
                                    "p-4 rounded-xl border-2 transition-all",
                                    isSelected
                                        ? "border-[var(--color-primary)] bg-[var(--color-primary)]/10"
                                        : canAfford
                                            ? "border-transparent bg-[var(--color-bg-app)] hover:border-[var(--color-primary)]/50"
                                            : "border-transparent bg-gray-100 opacity-50 cursor-not-allowed"
                                )}
                            >
                                <div className="text-3xl text-center mb-2">{gift.emoji}</div>
                                <p className="text-sm font-medium text-center">
                                    {language === 'zh' ? gift.name : gift.name_en}
                                </p>
                                <p className="text-xs text-[var(--color-text-muted)] text-center mt-1">
                                    馃拵 {gift.cost} | +{gift.intimacyBoost}鉂わ笍
                                </p>
                            </button>
                        );
                    })}
                </div>

                {/* Result Message */}
                {result && (
                    <div className={cn(
                        "px-4 py-2 text-center text-sm font-medium",
                        result.success ? "text-green-600 bg-green-50" : "text-red-600 bg-red-50"
                    )}>
                        {result.success
                            ? (language === 'zh' ? '馃帀 绀肩墿鍙戦€佹垚鍔?' : '馃帀 Gift sent successfully!')
                            : (language === 'zh' ? '鉂?绉垎涓嶈冻' : '鉂?Insufficient points')
                        }
                    </div>
                )}

                {/* Send Button */}
                <div className="p-4 border-t border-[var(--color-border)]">
                    <button
                        onClick={handleSend}
                        disabled={!selectedGift || sending}
                        className={cn(
                            "w-full py-3 rounded-lg font-medium transition-all flex items-center justify-center gap-2",
                            selectedGift && !sending
                                ? "bg-[var(--color-primary)] text-white hover:bg-[var(--color-primary-hover)]"
                                : "bg-gray-200 text-gray-400 cursor-not-allowed"
                        )}
                    >
                        {sending ? (
                            <>
                                <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                                {language === 'zh' ? '鍙戦€佷腑...' : 'Sending...'}
                            </>
                        ) : (
                            <>
                                <Gift size={20} />
                                {selectedGift
                                    ? (language === 'zh' ? `鍙戦€?${selectedGift.emoji} (${selectedGift.cost}绉垎)` : `Send ${selectedGift.emoji} (${selectedGift.cost} pts)`)
                                    : (language === 'zh' ? '閫夋嫨绀肩墿' : 'Select a gift')
                                }
                            </>
                        )}
                    </button>
                </div>
            </div>
        </div>
    );
}

