import React, { useState, useMemo, useEffect } from 'react';
import { X, Search, MessageSquare, ChevronRight } from 'lucide-react';
import { useChat } from '../context/ChatContext';
import { useLanguage } from '../../../context/LanguageContext';
import { cn } from '../../../utils/cn';

export default function MessageSearchPanel({ onClose, onSelectMessage, currentChatId }) {
    const { chats, personas } = useChat();
    const { t, language } = useLanguage();
    const [searchTerm, setSearchTerm] = useState('');
    const [debouncedTerm, setDebouncedTerm] = useState('');
    const [searchScope, setSearchScope] = useState(currentChatId ? 'current' : 'all'); // 'all' or 'current'
    const [fileType, setFileType] = useState('all'); // 'all', 'text', 'image', 'file', 'audio'

    useEffect(() => {
        const timer = setTimeout(() => {
            setDebouncedTerm(searchTerm);
        }, 300);
        return () => clearTimeout(timer);
    }, [searchTerm]);

    // Search through all messages
    const searchResults = useMemo(() => {
        if (!debouncedTerm.trim() || debouncedTerm.length < 2) return [];
        if (!chats || !personas) return [];

        const results = [];
        const term = debouncedTerm.toLowerCase();

        const chatsToSearch = searchScope === 'current' && currentChatId
            ? chats.filter(c => c.id === currentChatId)
            : chats;

        chatsToSearch.forEach(chat => {
            if (!chat || !chat.messages) return;

            chat.messages.forEach(msg => {
                let matchesType = true;
                const content = String(msg.content || '');

                // Filter by type
                if (fileType === 'image') {
                    matchesType = content.includes('[IMG:');
                } else if (fileType === 'file') {
                    matchesType = content.includes('[FILE]');
                } else if (fileType === 'audio') {
                    matchesType = content.includes('[VOICE:');
                } else if (fileType === 'text') {
                    matchesType = !content.includes('[IMG:') && !content.includes('[FILE]') && !content.includes('[VOICE:');
                }

                if (!matchesType) return;

                // For specialized types, we might want to match generic terms or just show all if search is generic
                // But typically search matches content.
                // If it's a file, we search filename.
                let contentToMatch = content;
                if (content.includes('[FILE]')) {
                    contentToMatch = content.replace('[FILE]', '').trim();
                } else if (content.includes('[IMG:')) {
                    contentToMatch = "Image";
                }

                if (contentToMatch.toLowerCase().includes(term)) {
                    const sender = msg.senderId === 'user-me'
                        ? { name: language === 'zh' ? '鎴? : 'Me' }
                        : personas.find(p => p.id === msg.senderId);

                    results.push({
                        chatId: chat.id,
                        chatName: chat.name || getChatName(chat),
                        messageId: msg.id,
                        content: content,
                        senderName: sender ? (language === 'zh' ? sender.name_zh || sender.name : sender.name) : 'Unknown',
                        timestamp: msg.timestamp
                    });
                }
            });
        });

        // Sort by timestamp, newest first
        return results.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp)).slice(0, 50);
    }, [debouncedTerm, chats, personas, language, searchScope, currentChatId, fileType]);

    const getChatName = (chat) => {
        if (!chat || !chat.participants) return 'Chat';
        const otherId = chat.participants.find(p => p !== 'user-me');
        const persona = personas?.find(p => p.id === otherId);
        return persona ? (language === 'zh' ? persona.name_zh || persona.name : persona.name) : 'Chat';
    };

    const highlightMatch = (text, term) => {
        if (!term || !text) return text;
        try {
            // Escape special regex characters
            const escapedTerm = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const regex = new RegExp(`(${escapedTerm})`, 'gi');
            const parts = text.split(regex);
            return parts.map((part, i) =>
                part.toLowerCase() === term.toLowerCase()
                    ? <mark key={i} className="bg-yellow-200 text-yellow-900 px-0.5 rounded">{part}</mark>
                    : part
            );
        } catch (e) {
            console.error("Search highlight error:", e);
            return text;
        }
    };

    const formatTime = (timestamp) => {
        try {
            const date = new Date(timestamp);
            if (isNaN(date.getTime())) return '';

            const now = new Date();
            const diff = now - date;
            const days = Math.floor(diff / 86400000);

            if (days === 0) {
                return date.toLocaleTimeString(language === 'zh' ? 'zh-CN' : 'en-US', {
                    hour: '2-digit',
                    minute: '2-digit'
                });
            } else if (days === 1) {
                return language === 'zh' ? '鏄ㄥぉ' : 'Yesterday';
            } else if (days < 7) {
                return date.toLocaleDateString(language === 'zh' ? 'zh-CN' : 'en-US', { weekday: 'short' });
            } else {
                return date.toLocaleDateString(language === 'zh' ? 'zh-CN' : 'en-US', {
                    month: 'short',
                    day: 'numeric'
                });
            }
        } catch (e) {
            return '';
        }
    };

    return (
        <div className="fixed inset-0 z-50 bg-white flex flex-col">
            {/* Header */}
            <div className="flex items-center gap-3 px-4 py-3 border-b border-[var(--color-border)]">
                <button onClick={onClose} className="text-[var(--color-text-muted)]">
                    <X size={24} />
                </button>

                <div className="flex-1 relative">
                    <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)]" />
                    <input
                        type="text"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        placeholder={language === 'zh' ? '鎼滅储鑱婂ぉ璁板綍...' : 'Search messages...'}
                        autoFocus
                        className="w-full pl-10 pr-4 py-2 bg-[var(--color-bg-app)] rounded-lg text-[15px] outline-none focus:ring-2 ring-[var(--color-primary)]/30"
                    />
                </div>
            </div>

            {/* Filters */}
            <div className="px-4 py-2 bg-white border-b border-[var(--color-border-light)] flex flex-wrap gap-2">
                {currentChatId && (
                    <div className="flex bg-[var(--color-bg-app)] rounded-lg p-0.5">
                        <button
                            onClick={() => setSearchScope('current')}
                            className={cn(
                                "px-3 py-1 text-xs font-medium rounded-md transition-all",
                                searchScope === 'current' ? "bg-white shadow-sm text-[var(--color-primary)]" : "text-[var(--color-text-muted)]"
                            )}
                        >
                            {language === 'zh' ? '褰撳墠鑱婂ぉ' : 'Current Chat'}
                        </button>
                        <button
                            onClick={() => setSearchScope('all')}
                            className={cn(
                                "px-3 py-1 text-xs font-medium rounded-md transition-all",
                                searchScope === 'all' ? "bg-white shadow-sm text-[var(--color-primary)]" : "text-[var(--color-text-muted)]"
                            )}
                        >
                            {language === 'zh' ? '鎵€鏈夎亰澶? : 'All Chats'}
                        </button>
                    </div>
                )}

                <div className="flex bg-[var(--color-bg-app)] rounded-lg p-0.5 overflow-x-auto no-scrollbar">
                    {['all', 'text', 'image', 'file', 'audio'].map(type => (
                        <button
                            key={type}
                            onClick={() => setFileType(type)}
                            className={cn(
                                "px-3 py-1 text-xs font-medium rounded-md transition-all whitespace-nowrap",
                                fileType === type ? "bg-white shadow-sm text-[var(--color-primary)]" : "text-[var(--color-text-muted)]"
                            )}
                        >
                            {type === 'all' ? (language === 'zh' ? '鍏ㄩ儴' : 'All') :
                                type === 'text' ? (language === 'zh' ? '鏂囨湰' : 'Text') :
                                    type === 'image' ? (language === 'zh' ? '鍥剧墖' : 'Image') :
                                        type === 'file' ? (language === 'zh' ? '鏂囦欢' : 'File') :
                                            (language === 'zh' ? '璇煶' : 'Audio')}
                        </button>
                    ))}
                </div>
            </div>

            {/* Results */}
            <div className="flex-1 overflow-y-auto">
                {searchTerm.length < 2 ? (
                    <div className="p-8 text-center text-[var(--color-text-muted)]">
                        <MessageSquare size={48} className="mx-auto mb-4 opacity-50" />
                        <p>{language === 'zh' ? '杈撳叆鍏抽敭璇嶆悳绱? : 'Enter keywords to search'}</p>
                        <p className="text-sm mt-1">{language === 'zh' ? '鑷冲皯2涓瓧绗? : 'At least 2 characters'}</p>
                    </div>
                ) : searchResults.length === 0 ? (
                    <div className="p-8 text-center text-[var(--color-text-muted)]">
                        <Search size={48} className="mx-auto mb-4 opacity-50" />
                        <p>{language === 'zh' ? '鏈壘鍒扮粨鏋? : 'No results found'}</p>
                    </div>
                ) : (
                    <>
                        <div className="px-4 py-2 bg-[var(--color-bg-app)] text-sm text-[var(--color-text-muted)]">
                            {language === 'zh' ? `鎵惧埌 ${searchResults.length} 鏉＄粨鏋渀 : `${searchResults.length} results found`}
                        </div>
                        {searchResults.map((result, index) => (
                            <button
                                key={`${result.chatId}-${result.messageId}`}
                                onClick={() => {
                                    onSelectMessage?.(result.chatId, result.messageId);
                                    onClose?.();
                                }}
                                className="w-full px-4 py-3 flex items-start gap-3 hover:bg-[var(--color-bg-app)] transition-colors border-b border-[var(--color-border-light)]"
                            >
                                <div className="w-10 h-10 rounded-full bg-[var(--color-primary)] flex items-center justify-center text-white flex-shrink-0">
                                    <MessageSquare size={18} />
                                </div>

                                <div className="flex-1 min-w-0 text-left">
                                    <div className="flex items-center justify-between">
                                        <span className="font-medium text-[var(--color-text-main)] text-[15px]">
                                            {result.chatName}
                                        </span>
                                        <span className="text-xs text-[var(--color-text-muted)]">
                                            {formatTime(result.timestamp)}
                                        </span>
                                    </div>
                                    <p className="text-sm text-[var(--color-primary)] mt-0.5">
                                        {result.senderName}
                                    </p>
                                    <p className="text-sm text-[var(--color-text-main)] mt-1 line-clamp-2">
                                        {highlightMatch(result.content, debouncedTerm)}
                                    </p>
                                </div>

                                <ChevronRight size={20} className="text-[var(--color-text-muted)] flex-shrink-0 mt-2" />
                            </button>
                        ))}
                    </>
                )}
            </div>
        </div>
    );
}

import React from 'react';
import { useLanguage } from '../../../context/LanguageContext';
import { cn } from '../../../utils/cn';

export default function QuotedMessage({ quotedMessage, senderName, onClick }) {
    const { t } = useLanguage();

    if (!quotedMessage) return null;

    // Truncate long messages
    const maxLength = 50;
    const displayContent = quotedMessage.content.length > maxLength
        ? quotedMessage.content.slice(0, maxLength) + '...'
        : quotedMessage.content;

    return (
        <div
            onClick={onClick}
            className={cn(
                "px-2 py-1 mb-1 border-l-2 border-[var(--color-primary)] bg-black/5 rounded-r",
                "text-xs text-gray-600 cursor-pointer hover:bg-black/10 transition-colors"
            )}
        >
            <span className="font-medium text-[var(--color-primary)]">
                {senderName}
            </span>
            <p className="text-gray-500 truncate">{displayContent}</p>
        </div>
    );
}

import React, { useState } from 'react';
import { X, Gift, Sparkles } from 'lucide-react';
import { useSocial } from '../../../context/SocialContext';
import { useLanguage } from '../../../context/LanguageContext';
import { cn } from '../../../utils/cn';

// Red packet amounts
const AMOUNTS = [10, 20, 50, 100, 200, 520];

export default function RedPacketPanel({ recipientName, onClose, onSend }) {
    const { points, addPoints } = useSocial();
    const { language } = useLanguage();
    const [amount, setAmount] = useState(null);
    const [message, setMessage] = useState('');
    const [sending, setSending] = useState(false);
    const [opened, setOpened] = useState(false);
    const [receivedAmount, setReceivedAmount] = useState(null);

    const canAfford = amount && points >= amount;

    const handleSend = () => {
        if (!canAfford) return;
        setSending(true);

        setTimeout(() => {
            setSending(false);
            onSend?.({ amount, message });
            onClose?.();
        }, 800);
    };

    // For receiving red packets
    const handleOpen = () => {
        setOpened(true);
        // Random amount between 1 and the packet amount
        const received = Math.floor(Math.random() * (amount || 50)) + 1;
        setReceivedAmount(received);
        addPoints(received);
    };

    return (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4" onClick={onClose}>
            <div
                className="w-full max-w-xs overflow-hidden animate-scale-in"
                onClick={e => e.stopPropagation()}
            >
                {/* Red Packet Design */}
                <div className="bg-gradient-to-b from-red-500 to-red-600 rounded-xl overflow-hidden shadow-2xl">
                    {/* Top Section */}
                    <div className="relative p-6 text-center text-yellow-100">
                        <button
                            onClick={onClose}
                            className="absolute top-3 right-3 text-white/60 hover:text-white"
                        >
                            <X size={24} />
                        </button>

                        <div className="w-16 h-16 mx-auto bg-yellow-500/20 rounded-full flex items-center justify-center mb-4">
                            <Gift size={32} className="text-yellow-400" />
                        </div>

                        <h3 className="text-xl font-bold text-yellow-400">
                            {language === 'zh' ? '鍙戠孩鍖? : 'Send Red Packet'}
                        </h3>
                        <p className="text-sm mt-1 text-yellow-200/80">
                            {recipientName ?
                                (language === 'zh' ? `鍙戠粰 ${recipientName}` : `To ${recipientName}`)
                                : (language === 'zh' ? '閫夋嫨閲戦' : 'Select amount')
                            }
                        </p>
                    </div>

                    {/* Amount Grid */}
                    <div className="bg-white/10 p-4">
                        <div className="grid grid-cols-3 gap-2">
                            {AMOUNTS.map(amt => (
                                <button
                                    key={amt}
                                    onClick={() => setAmount(amt)}
                                    disabled={points < amt}
                                    className={cn(
                                        "py-3 rounded-lg text-center font-medium transition-all",
                                        amount === amt
                                            ? "bg-yellow-400 text-red-700"
                                            : points >= amt
                                                ? "bg-white/20 text-white hover:bg-white/30"
                                                : "bg-white/5 text-white/30 cursor-not-allowed"
                                    )}
                                >
                                    馃挵 {amt}
                                </button>
                            ))}
                        </div>

                        <p className="text-center text-yellow-200/60 text-xs mt-3">
                            {language === 'zh' ? '褰撳墠绉垎' : 'Current points'}: {points}
                        </p>
                    </div>

                    {/* Message Input */}
                    <div className="p-4 bg-white/10">
                        <input
                            type="text"
                            value={message}
                            onChange={(e) => setMessage(e.target.value)}
                            placeholder={language === 'zh' ? '鎭枩鍙戣储锛屽ぇ鍚夊ぇ鍒? : 'Best wishes!'}
                            maxLength={30}
                            className="w-full px-4 py-2 bg-white/20 rounded-lg text-white placeholder:text-white/40 text-center outline-none"
                        />
                    </div>

                    {/* Bottom Gold Bar */}
                    <div className="h-8 bg-gradient-to-r from-yellow-400 via-yellow-500 to-yellow-400 relative">
                        <div className="absolute inset-0 flex items-center justify-center">
                            <Sparkles size={16} className="text-yellow-700" />
                        </div>
                    </div>

                    {/* Send Button */}
                    <div className="p-4 bg-red-700">
                        <button
                            onClick={handleSend}
                            disabled={!canAfford || sending}
                            className={cn(
                                "w-full py-3 rounded-lg font-bold text-lg transition-all flex items-center justify-center gap-2",
                                canAfford && !sending
                                    ? "bg-yellow-400 text-red-700 hover:bg-yellow-300"
                                    : "bg-gray-400/50 text-white/50 cursor-not-allowed"
                            )}
                        >
                            {sending ? (
                                <div className="w-6 h-6 border-2 border-red-700/30 border-t-red-700 rounded-full animate-spin" />
                            ) : (
                                <>
                                    <Gift size={20} />
                                    {amount
                                        ? (language === 'zh' ? `濉炲叆 ${amount} 绉垎` : `Send ${amount} points`)
                                        : (language === 'zh' ? '閫夋嫨閲戦' : 'Select amount')
                                    }
                                </>
                            )}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}

