import React, { useState, useEffect, useCallback } from 'react';
import { X, RotateCcw } from 'lucide-react';
import { useLanguage } from '../../../context/LanguageContext';
import { cn } from '../../../utils/cn';

// Game choices
const CHOICES = [
    { id: 'rock', emoji: '鉁?, name: '鐭冲ご', name_en: 'Rock' },
    { id: 'paper', emoji: '鉁?, name: '甯?, name_en: 'Paper' },
    { id: 'scissors', emoji: '鉁岋笍', name: '鍓垁', name_en: 'Scissors' }
];

const OUTCOMES = {
    rock: { rock: 'draw', paper: 'lose', scissors: 'win' },
    paper: { rock: 'win', paper: 'draw', scissors: 'lose' },
    scissors: { rock: 'lose', paper: 'win', scissors: 'draw' }
};

export default function RockPaperScissors({ aiName, onClose, onResult }) {
    const { t, language } = useLanguage();
    const [playerChoice, setPlayerChoice] = useState(null);
    const [aiChoice, setAiChoice] = useState(null);
    const [result, setResult] = useState(null);
    const [countdown, setCountdown] = useState(null);
    const [score, setScore] = useState({ player: 0, ai: 0 });
    const [round, setRound] = useState(1);

    // AI makes its choice after player
    useEffect(() => {
        if (playerChoice && !aiChoice) {
            setCountdown(3);
        }
    }, [playerChoice, aiChoice]);

    // Countdown and reveal
    useEffect(() => {
        if (countdown === null) return;

        if (countdown > 0) {
            const timer = setTimeout(() => setCountdown(countdown - 1), 500);
            return () => clearTimeout(timer);
        } else {
            // AI picks randomly
            const randomChoice = CHOICES[Math.floor(Math.random() * CHOICES.length)];
            setAiChoice(randomChoice);

            // Determine result
            const outcome = OUTCOMES[playerChoice.id][randomChoice.id];
            setResult(outcome);

            // Update score
            if (outcome === 'win') {
                setScore(prev => ({ ...prev, player: prev.player + 1 }));
            } else if (outcome === 'lose') {
                setScore(prev => ({ ...prev, ai: prev.ai + 1 }));
            }
        }
    }, [countdown, playerChoice]);

    const handleChoice = (choice) => {
        if (playerChoice) return; // Already chose
        setPlayerChoice(choice);
    };

    const handlePlayAgain = () => {
        setPlayerChoice(null);
        setAiChoice(null);
        setResult(null);
        setCountdown(null);
        setRound(prev => prev + 1);
    };

    const handleFinish = () => {
        const finalResult = score.player > score.ai ? 'win' : score.player < score.ai ? 'lose' : 'draw';
        onResult?.({ result: finalResult, score, rounds: round });
        onClose?.();
    };

    const getResultMessage = () => {
        if (!result) return '';
        if (result === 'win') return language === 'zh' ? '浣犺耽浜? 馃帀' : 'You win! 馃帀';
        if (result === 'lose') return language === 'zh' ? `${aiName} 璧簡!` : `${aiName} wins!`;
        return language === 'zh' ? '骞冲眬!' : 'Draw!';
    };

    const getResultColor = () => {
        if (!result) return '';
        if (result === 'win') return 'text-green-500';
        if (result === 'lose') return 'text-red-500';
        return 'text-yellow-500';
    };

    return (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4" onClick={onClose}>
            <div
                className="bg-white rounded-xl w-full max-w-sm overflow-hidden animate-scale-in"
                onClick={e => e.stopPropagation()}
            >
                {/* Header */}
                <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--color-border)] bg-gradient-to-r from-[var(--color-primary)] to-[var(--color-primary-hover)]">
                    <h3 className="font-bold text-white text-lg">
                        {language === 'zh' ? '鉁?鐭冲ご鍓垁甯?鉁岋笍' : '鉁?Rock Paper Scissors 鉁岋笍'}
                    </h3>
                    <button onClick={onClose} className="text-white/80 hover:text-white">
                        <X size={24} />
                    </button>
                </div>

                {/* Score */}
                <div className="flex justify-between items-center px-6 py-3 bg-[var(--color-bg-app)]">
                    <div className="text-center">
                        <p className="text-sm text-[var(--color-text-muted)]">{t('you') || 'You'}</p>
                        <p className="text-2xl font-bold text-[var(--color-primary)]">{score.player}</p>
                    </div>
                    <div className="text-center">
                        <p className="text-sm text-[var(--color-text-muted)]">{language === 'zh' ? '绗? : 'Round'} {round} {language === 'zh' ? '杞? : ''}</p>
                        <p className="text-lg font-medium">VS</p>
                    </div>
                    <div className="text-center">
                        <p className="text-sm text-[var(--color-text-muted)]">{aiName}</p>
                        <p className="text-2xl font-bold text-red-500">{score.ai}</p>
                    </div>
                </div>

                {/* Game Area */}
                <div className="p-6">
                    {/* Choices Display */}
                    <div className="flex justify-center items-center gap-8 mb-6">
                        <div className="text-center">
                            <div className={cn(
                                "w-20 h-20 rounded-full bg-blue-100 flex items-center justify-center text-4xl transition-all",
                                playerChoice && "animate-bounce-once"
                            )}>
                                {playerChoice ? playerChoice.emoji : '鉂?}
                            </div>
                            <p className="mt-2 text-sm font-medium">{t('you') || 'You'}</p>
                        </div>

                        <div className="text-2xl font-bold text-[var(--color-text-muted)]">
                            {countdown !== null && countdown > 0 ? countdown : 'VS'}
                        </div>

                        <div className="text-center">
                            <div className={cn(
                                "w-20 h-20 rounded-full bg-red-100 flex items-center justify-center text-4xl transition-all",
                                aiChoice && "animate-bounce-once"
                            )}>
                                {aiChoice ? aiChoice.emoji : (countdown !== null ? '馃' : '鉂?)}
                            </div>
                            <p className="mt-2 text-sm font-medium">{aiName}</p>
                        </div>
                    </div>

                    {/* Result */}
                    {result && (
                        <div className={cn("text-center text-xl font-bold mb-4", getResultColor())}>
                            {getResultMessage()}
                        </div>
                    )}

                    {/* Choice Buttons */}
                    {!playerChoice && (
                        <div>
                            <p className="text-center text-sm text-[var(--color-text-muted)] mb-4">
                                {language === 'zh' ? '閫夋嫨浣犵殑鍑烘嫑' : 'Make your choice'}
                            </p>
                            <div className="flex justify-center gap-4">
                                {CHOICES.map(choice => (
                                    <button
                                        key={choice.id}
                                        onClick={() => handleChoice(choice)}
                                        className="w-16 h-16 rounded-full bg-[var(--color-bg-app)] hover:bg-[var(--color-primary)] hover:text-white text-3xl transition-all hover:scale-110 active:scale-95"
                                    >
                                        {choice.emoji}
                                    </button>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Play Again / Finish */}
                    {result && (
                        <div className="flex gap-3">
                            <button
                                onClick={handlePlayAgain}
                                className="flex-1 py-3 bg-[var(--color-primary)] text-white rounded-lg font-medium flex items-center justify-center gap-2 hover:bg-[var(--color-primary-hover)] transition-colors"
                            >
                                <RotateCcw size={18} />
                                {language === 'zh' ? '鍐嶆潵涓€灞€' : 'Play Again'}
                            </button>
                            <button
                                onClick={handleFinish}
                                className="flex-1 py-3 bg-[var(--color-bg-app)] text-[var(--color-text-main)] rounded-lg font-medium hover:bg-gray-200 transition-colors"
                            >
                                {language === 'zh' ? '缁撴潫' : 'Finish'}
                            </button>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

import React, { useState, useRef } from 'react';
import { Smile, Mic, Paperclip, Plus, Heart, Keyboard, Gift, Coins, Gamepad2, BarChart3, X } from 'lucide-react';
import { cn } from '../../../../utils/cn';
import { useLanguage } from '../../../../context/LanguageContext';
import EmojiPicker from '../../../../components/EmojiPicker';
import StickerPicker from '../../../../components/StickerPicker';
import FileUploader from '../../../../components/FileUploader';

export default function ChatComposer({
    onSendMessage,
    quotedMessage,
    onCancelQuote,
    chatId,
    personas,
    headerInfo, // For sticker picker
    // Menu triggers
    onOpenGift,
    onOpenRedPacket,
    onOpenGame,
    onOpenPoll,
    onFileSelect
}) {
    const { t, language } = useLanguage();
    const [inputValue, setInputValue] = useState('');
    const [showEmojiPicker, setShowEmojiPicker] = useState(false);
    const [showStickerPicker, setShowStickerPicker] = useState(false);
    const [showPlusMenu, setShowPlusMenu] = useState(false);
    const [isRecordingMode, setIsRecordingMode] = useState(false);
    const [isRecording, setIsRecording] = useState(false);
    const [recordingStart, setRecordingStart] = useState(0);
    const [showFileUploader, setShowFileUploader] = useState(false);

    // @mention state
    const [showMentionDropdown, setShowMentionDropdown] = useState(false);
    const [mentionQuery, setMentionQuery] = useState('');
    const inputRef = useRef(null);

    // Helpers
    const getSenderName = (senderId) => {
        if (senderId === 'user-me') return t('you');
        const sender = personas.find(p => p.id === senderId);
        return language === 'zh' ? (sender?.name_zh || sender?.name) : sender?.name;
    };

    const mentionCandidates = chat ? chat.participants
        .filter(pid => pid !== 'user-me')
        .map(pid => personas.find(p => p.id === pid))
        .filter(p => p && (p.name.toLowerCase().includes(mentionQuery) || (p.name_zh || '').includes(mentionQuery)))
        : [];

    // Handlers
    const handleSend = (e) => {
        e?.preventDefault();
        if (!inputValue.trim()) return;
        onSendMessage(inputValue, quotedMessage?.id);
        setInputValue('');
        onCancelQuote();
    };

    const handleInputChange = (e) => {
        const value = e.target.value;
        setInputValue(value);

        // Check for @ trigger
        const lastAtIndex = value.lastIndexOf('@');
        if (lastAtIndex !== -1) {
            const textAfterAt = value.slice(lastAtIndex + 1);
            if (lastAtIndex === 0 || value[lastAtIndex - 1] === ' ') {
                setMentionQuery(textAfterAt.toLowerCase());
                setShowMentionDropdown(true);
                return;
            }
        }
        setShowMentionDropdown(false);
    };

    const handleMentionSelect = (person) => {
        const lastAtIndex = inputValue.lastIndexOf('@');
        const beforeAt = inputValue.slice(0, lastAtIndex);
        const personName = language === 'zh' ? (person.name_zh || person.name) : person.name;
        setInputValue(beforeAt + '@' + personName + ' ');
        setShowMentionDropdown(false);
        inputRef.current?.focus();
    };

    const handleEmojiSelect = (emoji) => {
        setInputValue(prev => prev + emoji);
    };

    const handleStickerSelect = (stickerEmoji) => {
        onSendMessage(`[STICKER:${stickerEmoji}]`);
        setShowStickerPicker(false);
    };

    const closeAll = () => {
        setShowEmojiPicker(false);
        setShowStickerPicker(false);
        setShowPlusMenu(false);
    };

    return (
        <div className="flex flex-col bg-[var(--color-bg-chat)] relative z-20">
            {/* Quoted Preview */}
            {quotedMessage && (
                <div className="px-3 py-2 bg-gray-100 border-t border-gray-200 flex items-center justify-between">
                    <div className="flex items-center gap-2 flex-1 min-w-0">
                        <div className="w-1 h-8 bg-[var(--color-primary)] rounded-full flex-shrink-0" />
                        <div className="min-w-0">
                            <p className="text-xs font-medium text-[var(--color-primary)]">
                                {t('reply_to')} {getSenderName(quotedMessage.senderId)}
                            </p>
                            <p className="text-xs text-gray-500 truncate">
                                {quotedMessage.content.slice(0, 50)}...
                            </p>
                        </div>
                    </div>
                    <button onClick={onCancelQuote} className="p-1 hover:bg-gray-200 rounded text-gray-500">
                        <X size={16} />
                    </button>
                </div>
            )}

            <div className="p-4">
                <div className="bg-white rounded-2xl shadow-lg border border-[var(--color-border-light)] p-2">
                    <form onSubmit={handleSend} className="flex items-end gap-2">
                        <button
                            type="button"
                            className={cn("p-2 rounded-full hover:bg-gray-100 transition-colors mb-0.5", isRecordingMode ? "text-[var(--color-text-main)]" : "text-[var(--color-text-muted)]")}
                            onClick={() => setIsRecordingMode(!isRecordingMode)}
                        >
                            {isRecordingMode ? <Keyboard size={24} /> : <Mic size={24} />}
                        </button>

                        {isRecordingMode ? (
                            <button
                                type="button"
                                onMouseDown={(e) => { e.preventDefault(); setIsRecording(true); setRecordingStart(Date.now()); }}
                                onMouseUp={(e) => {
                                    e.preventDefault();
                                    if (isRecording) {
                                        setIsRecording(false);
                                        const duration = Math.round((Date.now() - recordingStart) / 1000);
                                        if (duration >= 1) onSendMessage(`[VOICE:${duration}s]`);
                                    }
                                }}
                                onMouseLeave={() => setIsRecording(false)}
                                className={cn(
                                    "flex-1 rounded-xl border-none px-4 py-3 text-[15px] font-medium transition-all select-none text-center shadow-inner",
                                    isRecording ? "bg-[var(--color-primary-light)] text-[var(--color-primary-active)] scale-95" : "bg-gray-100 hover:bg-gray-200 text-[var(--color-text-main)]"
                                )}
                            >
                                {isRecording ? (language === 'zh' ? '鏉惧紑 鍙戦€? : 'Release to Send') : (language === 'zh' ? '鎸変綇 璇磋瘽' : 'Hold to Talk')}
                            </button>
                        ) : (
                            <div className="flex-1 relative min-h-[44px] flex items-center">
                                <input
                                    ref={inputRef}
                                    type="text"
                                    value={inputValue}
                                    onChange={handleInputChange}
                                    placeholder={t('type_message')}
                                    className="w-full bg-transparent border-none px-2 py-2 text-[15px] text-[var(--color-text-main)] placeholder:text-[var(--color-text-muted)] focus:outline-none"
                                />
                                {showMentionDropdown && mentionCandidates.length > 0 && (
                                    <div className="absolute bottom-full left-0 mb-3 bg-white rounded-xl shadow-float border border-[var(--color-border)] py-2 min-w-[200px] max-h-[240px] overflow-y-auto z-40">
                                        {/* Simplified Mention List for brevity */}
                                        {mentionCandidates.map(p => (
                                            <button key={p.id} onClick={() => handleMentionSelect(p)} className="block w-full text-left px-4 py-2 hover:bg-gray-50">@{p.name}</button>
                                        ))}
                                    </div>
                                )}
                            </div>
                        )}

                        <div className="flex items-center gap-1 mb-0.5">
                            <button
                                type="button"
                                className={cn("p-2 rounded-full hover:bg-gray-100 transition-colors", showEmojiPicker ? "text-[var(--color-primary)]" : "text-[var(--color-text-muted)]")}
                                onClick={() => { closeAll(); setShowEmojiPicker(!showEmojiPicker); }}
                            >
                                <Smile size={24} />
                            </button>
                            <button
                                type="button"
                                className={cn("p-2 rounded-full hover:bg-gray-100 transition-colors", showStickerPicker ? "text-[var(--color-primary)]" : "text-[var(--color-text-muted)]")}
                                onClick={() => { closeAll(); setShowStickerPicker(!showStickerPicker); }}
                            >
                                <Heart size={24} />
                            </button>

                            {inputValue.trim() ? (
                                <button type="submit" className="ml-1 bg-[var(--color-primary)] text-white px-5 py-2 rounded-xl text-[15px] font-medium hover:bg-[var(--color-primary-hover)]">
                                    {t('send')}
                                </button>
                            ) : (
                                <button
                                    type="button"
                                    className={cn("p-2 rounded-full hover:bg-gray-100 transition-colors", showPlusMenu ? "text-[var(--color-primary)]" : "text-[var(--color-text-muted)]")}
                                    onClick={() => { closeAll(); setShowPlusMenu(!showPlusMenu); }}
                                >
                                    <Plus size={24} />
                                </button>
                            )}
                        </div>
                    </form>
                </div>

                {/* Popups */}
                {showEmojiPicker && <div className="absolute bottom-full left-0 mb-2 z-30"><EmojiPicker onSelect={handleEmojiSelect} onClose={() => setShowEmojiPicker(false)} /></div>}
                {showStickerPicker && <div className="absolute bottom-full left-0 mb-2 z-30"><StickerPicker aiId={headerInfo.id} onSelect={handleStickerSelect} onClose={() => setShowStickerPicker(false)} /></div>}
                {showPlusMenu && (
                    <div className="absolute bottom-full right-2 mb-2 bg-white rounded-xl shadow-xl border border-gray-200 p-2 min-w-[200px] grid grid-cols-4 gap-2 z-30 animate-scale-in">
                        <MenuButton icon={Paperclip} label={t('file')} onClick={() => setShowFileUploader(true)} color="text-blue-500" bg="bg-blue-50" />
                        <MenuButton icon={Gift} label={language === 'zh' ? '绀肩墿' : 'Gift'} onClick={onOpenGift} color="text-pink-500" bg="bg-pink-50" />
                        <MenuButton icon={Coins} label={language === 'zh' ? '绾㈠寘' : 'Packet'} onClick={onOpenRedPacket} color="text-red-500" bg="bg-red-50" />
                        <MenuButton icon={Gamepad2} label={language === 'zh' ? '娓告垙' : 'Game'} onClick={onOpenGame} color="text-purple-500" bg="bg-purple-50" />
                        <MenuButton icon={BarChart3} label={language === 'zh' ? '鎶曠エ' : 'Poll'} onClick={onOpenPoll} color="text-orange-500" bg="bg-orange-50" />
                    </div>
                )}
            </div>

            {showFileUploader && (
                <div className="absolute bottom-16 left-2 mb-2 z-40">
                    <FileUploader onFileSelect={(file) => { onFileSelect(file); setShowFileUploader(false); closeAll(); }} onClose={() => setShowFileUploader(false)} />
                </div>
            )}
        </div>
    );
}

function MenuButton({ icon: Icon, label, onClick, color, bg }) {
    return (
        <button onClick={onClick} className="flex flex-col items-center justify-center gap-1 p-2 rounded-lg hover:bg-gray-100 transition-colors">
            <div className={cn("w-12 h-12 rounded-xl flex items-center justify-center mb-1", bg, color)}>
                <Icon size={24} />
            </div>
            <span className="text-xs text-gray-600">{label}</span>
        </button>
    );
}

import React, { useRef, useEffect } from 'react';
import { cn } from '../../../../utils/cn';
import { formatTimeSeparator, shouldShowTimeSeparator } from '../../../../utils/formatTime';
import { downloadFile, formatFileSize } from '../../../../utils/fileUtils';
import { Paperclip, MoreHorizontal, Coins, Gamepad2 } from 'lucide-react';
import { useLanguage } from '../../../../context/LanguageContext';
import QuotedMessage from '../QuotedMessage';
import PollMessage from '../PollMessage';
import { GeneratedFileMessage } from '../FileMessage';

export default function MessageTimeline({
    chat,
    currentUser,
    personas,
    onContextMenu,
    onVotePoll
}) {
    const { language } = useLanguage();
    const messagesEndRef = useRef(null);

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: "auto" });
    }, [chat?.messages]);

    const getSenderName = (senderId) => {
        if (senderId === 'user-me') return 'You'; // Simplified, trans handled in parent usually or hook
        const sender = personas.find(p => p.id === senderId);
        return language === 'zh' ? (sender?.name_zh || sender?.name) : sender?.name;
    };

    const getQuotedMessageData = (quotedId) => {
        if (!quotedId) return null;
        const msg = chat.messages.find(m => m.id === quotedId);
        if (!msg) return null;
        return {
            ...msg,
            senderName: getSenderName(msg.senderId)
        };
    };

    return (
        <div className="flex-1 overflow-y-auto p-3 pb-20 md:pb-4">
            {chat.messages.map((msg, index) => {
                const isMe = msg.senderId === 'user-me';
                const sender = isMe ? currentUser : personas.find(p => p.id === msg.senderId);
                const senderName = getSenderName(msg.senderId);

                let content = msg.content;
                let reaction = null;
                let type = 'text';
                let meta = null;

                // Parse custom message types (Legacy logic preserved)
                if (content.startsWith('[FILE]')) {
                    type = 'file';
                    content = content.replace('[FILE]', '').trim();
                } else if (content.startsWith('[STICKER:')) {
                    type = 'sticker';
                    const match = content.match(/\[STICKER:(.+?)\]/);
                    content = match ? match[1] : '';
                } else if (content.startsWith('[GIFT:')) {
                    type = 'gift';
                    const parts = content.match(/\[GIFT:(.+?):(.+?):(.+?)\]/);
                    if (parts) {
                        meta = { emoji: parts[1], name: parts[2], name_en: parts[3] };
                        content = language === 'zh' ? `閫佸嚭浜?${parts[2]}` : `Sent ${parts[3]}`;
                    }
                } else if (content.startsWith('[RED_PACKET:')) {
                    type = 'red_packet';
                    const parts = content.match(/\[RED_PACKET:(.+?):(.+?)\]/);
                    if (parts) {
                        meta = { amount: parts[1], message: parts[2] };
                        content = language === 'zh' ? '鏀跺埌绾㈠寘' : 'Red Packet';
                    }
                } else if (content.startsWith('[GAME:')) {
                    type = 'game';
                    content = content.replace('[GAME:', '').replace(']', '');
                } else if (content.startsWith('[POLL:')) {
                    type = 'poll';
                    const match = content.match(/\[POLL:(.+?)\]/);
                    if (match) {
                        const pollId = match[1];
                        const poll = chat.polls?.find(p => p.id === pollId);
                        if (poll) {
                            meta = { poll };
                        } else {
                            type = 'text';
                            content = '[Poll not found]';
                        }
                    }
                }

                const reactMatch = content.match(/\[REACT:(.+?)\]/);
                if (reactMatch) {
                    reaction = reactMatch[1];
                    content = content.replace(reactMatch[0], '').trim();
                }

                const prevMsg = index > 0 ? chat.messages[index - 1] : null;
                const showTimeSeparator = shouldShowTimeSeparator(prevMsg?.timestamp, msg.timestamp, 5);
                const quotedData = getQuotedMessageData(msg.quotedMessageId);

                return (
                    <React.Fragment key={msg.id}>
                        {showTimeSeparator && (
                            <div className="flex justify-center my-4">
                                <span className="px-3 py-1 bg-black/5 text-[var(--color-text-muted)] text-xs rounded-full">
                                    {formatTimeSeparator(msg.timestamp, language)}
                                </span>
                            </div>
                        )}

                        <div
                            className={cn("flex mb-4 animate-message-in group/msg", isMe ? "justify-end" : "justify-start")}
                            onContextMenu={(e) => onContextMenu(e, msg)}
                        >
                            <div className={cn("flex max-w-[75%] gap-2.5", isMe ? "flex-row-reverse" : "flex-row")}>
                                {/* Avatar */}
                                <div className="w-9 h-9 rounded-xl overflow-hidden flex-shrink-0 shadow-sm opacity-90 hover:opacity-100 transition-opacity">
                                    {sender?.avatar ? (
                                        <img src={sender.avatar} className="w-full h-full object-cover" alt="" />
                                    ) : (
                                        <div className="w-full h-full bg-gradient-to-br from-[var(--color-primary)] to-[var(--color-primary-active)] flex items-center justify-center text-white text-xs font-bold">
                                            {senderName?.charAt(0)}
                                        </div>
                                    )}
                                </div>

                                {/* Bubble */}
                                <div className="relative">
                                    <div className={cn(
                                        "relative shadow-sm transition-all duration-200",
                                        (type === 'text' || type === 'file')
                                            ? (isMe
                                                ? "px-4 py-2.5 bg-gradient-to-br from-[var(--color-primary)] to-[var(--color-primary-active)] text-white rounded-2xl rounded-tr-sm"
                                                : "px-4 py-2.5 bg-white text-[var(--color-text-main)] rounded-2xl rounded-tl-sm border border-[var(--color-border-light)]")
                                            : "bg-transparent"
                                    )}>
                                        {quotedData && (
                                            <QuotedMessage quotedMessage={quotedData} senderName={quotedData.senderName} />
                                        )}

                                        {type === 'sticker' ? (
                                            <div className="text-7xl drop-shadow-md hover:scale-110 transition-transform cursor-pointer origin-bottom">
                                                {content}
                                            </div>
                                        ) : type === 'gift' && meta ? (
                                            <div className="bg-gradient-to-r from-pink-500 to-rose-500 text-white p-3 rounded-2xl shadow-lg flex items-center gap-3 min-w-[160px]">
                                                <div className="text-3xl bg-white/20 p-2 rounded-xl">{meta.emoji}</div>
                                                <div>
                                                    <p className="font-bold text-sm">{language === 'zh' ? meta.name : meta.name_en}</p>
                                                    <p className="text-xs opacity-90">{language === 'zh' ? '璧犻€佺ぜ鐗? : 'Gift Sent'}</p>
                                                </div>
                                            </div>
                                        ) : type === 'red_packet' && meta ? (
                                            <div className="bg-gradient-to-r from-[#FA9D3B] to-[#F76B1C] text-white p-1 rounded-2xl shadow-md cursor-pointer hover:shadow-lg transition-shadow min-w-[220px]">
                                                <div className="flex items-center gap-3 p-3">
                                                    <div className="bg-[#FEF2DC] rounded-xl p-2.5 text-[#FA9D3B]">
                                                        <Coins size={24} />
                                                    </div>
                                                    <div>
                                                        <p className="font-bold">{meta.message || (language === 'zh' ? '鎭枩鍙戣储' : 'Best Wishes')}</p>
                                                        <p className="text-xs opacity-90">{language === 'zh' ? '鏌ョ湅绾㈠寘' : 'Open Packet'}</p>
                                                    </div>
                                                </div>
                                                <div className="bg-white/10 px-3 py-1 rounded-b-xl text-[10px] opacity-80">
                                                    Chat Buddy Red Packet
                                                </div>
                                            </div>
                                        ) : type === 'game' ? (
                                            <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100 flex flex-col items-center gap-2">
                                                <Gamepad2 size={24} className="text-[var(--color-primary)]" />
                                                <p className="font-medium text-center text-sm">{content}</p>
                                            </div>
                                        ) : type === 'poll' && meta?.poll ? (
                                            <div className="bg-white rounded-2xl overflow-hidden shadow-sm border border-gray-100 p-1">
                                                <PollMessage
                                                    poll={meta.poll}
                                                    onVote={(pollId, optionId) => onVotePoll(pollId, optionId)}
                                                />
                                            </div>
                                        ) : type === 'file' ? (
                                            <div className="flex items-center gap-3">
                                                <div className={cn("p-2 rounded-lg", isMe ? "bg-white/20" : "bg-gray-100")}>
                                                    <Paperclip size={20} className={isMe ? "text-white" : "text-[var(--color-text-muted)]"} />
                                                </div>
                                                <div className="text-sm underline underline-offset-2 opacity-90 hover:opacity-100 cursor-pointer">
                                                    {content}
                                                </div>
                                            </div>
                                        ) : (
                                            <p className="whitespace-pre-wrap break-words leading-relaxed">{content}</p>
                                        )}

                                        {reaction && (
                                            <span className="absolute -bottom-2 -right-2 bg-white rounded-full p-0.5 shadow-sm text-xs border border-gray-100 z-10 scale-110">
                                                {reaction}
                                            </span>
                                        )}
                                    </div>

                                    {/* Generated Files */}
                                    {msg.generatedFiles?.map((file, idx) => (
                                        <div key={idx} className="mt-2">
                                            <GeneratedFileMessage
                                                fileData={file}
                                                onDownload={() => downloadFile(file.filename, file.content)}
                                            />
                                        </div>
                                    ))}
                                </div>

                                <button
                                    onClick={(e) => onContextMenu(e, msg)}
                                    className={cn(
                                        "opacity-0 group-hover/msg:opacity-100 transition-opacity p-1.5 rounded-full hover:bg-gray-100 text-gray-400 self-center",
                                        isMe ? "mr-1" : "ml-1"
                                    )}
                                >
                                    <MoreHorizontal size={14} />
                                </button>
                            </div>
                        </div>
                    </React.Fragment>
                );
            })}
            <div ref={messagesEndRef} />
        </div>
    );
}

import React, { createContext, useContext, useCallback } from 'react';
import { useLocalStorage } from '../../../hooks/useLocalStorage';

const ChatActionContext = createContext();

export const useChatActions = () => {
    const context = useContext(ChatActionContext);
    if (!context) throw new Error('useChatActions must be used within a ChatProvider');
    return context;
};

export const ChatActionProvider = ({ children, chatsRef, setChats, scheduledMessagesRef }) => {

    // Logic: Send Message
    const sendMessage = useCallback((chatId, content, senderId = 'user-me') => {
        // Cancel any scheduled proactive messages when user sends a message
        if (scheduledMessagesRef.current) {
            scheduledMessagesRef.current.forEach((timeoutId, key) => {
                if (key.startsWith(chatId)) {
                    clearTimeout(timeoutId);
                    scheduledMessagesRef.current.delete(key);
                }
            });
        }

        setChats(prevChats => prevChats.map(chat => {
            if (chat.id !== chatId) return chat;

            const newMessage = {
                id: crypto.randomUUID(),
                senderId,
                content,
                timestamp: new Date().toISOString(),
                status: 'sent'
            };

            return {
                ...chat,
                messages: [...chat.messages, newMessage],
                lastMessage: newMessage
            };
        }));
    }, [setChats, scheduledMessagesRef]);

    // Logic: Create Chat
    const createChat = useCallback((name, selectedPersonaIds) => {
        const newChat = {
            id: crypto.randomUUID(),
            name,
            participants: ['user-me', ...selectedPersonaIds],
            messages: [],
            createdAt: new Date().toISOString()
        };
        setChats(prev => [newChat, ...prev]);
        return newChat.id;
    }, [setChats]);

    // Logic: Update Chat
    const updateChat = useCallback((chatId, updates) => {
        setChats(prev => prev.map(chat =>
            chat.id === chatId ? { ...chat, ...updates } : chat
        ));
    }, [setChats]);

    // Logic: Delete Chat
    const deleteChat = useCallback((id) => {
        // Clear scheduled messages for this chat
        if (scheduledMessagesRef.current) {
            scheduledMessagesRef.current.forEach((timeoutId, key) => {
                if (key.startsWith(id)) {
                    clearTimeout(timeoutId);
                    scheduledMessagesRef.current.delete(key);
                }
            });
        }
        setChats(prev => prev.filter(c => c.id !== id));
    }, [setChats, scheduledMessagesRef]);

    // Logic: Delete/Recall Message
    const deleteMessage = useCallback((chatId, messageId) => {
        setChats(prev => prev.map(chat => {
            if (chat.id !== chatId) return chat;
            const updatedMessages = chat.messages.filter(m => m.id !== messageId);
            return {
                ...chat,
                messages: updatedMessages,
                lastMessage: updatedMessages[updatedMessages.length - 1] || null
            };
        }));
    }, [setChats]);

    // Logic: Clear Chat History
    const clearChatMessages = useCallback((chatId) => {
        setChats(prev => prev.map(chat => {
            if (chat.id !== chatId) return chat;
            return {
                ...chat,
                messages: [],
                lastMessage: null,
                pinnedMessages: []
            };
        }));
    }, [setChats]);

    // Logic: Pin/Unpin Chat
    const pinChat = useCallback((chatId, isPinned) => {
        setChats(prev => prev.map(chat =>
            chat.id === chatId ? { ...chat, isPinned } : chat
        ));
    }, [setChats]);

    // Logic: Mark Chat as Unread
    const markChatUnread = useCallback((chatId, isUnread = true) => {
        setChats(prev => prev.map(chat =>
            chat.id === chatId ? { ...chat, isUnread } : chat
        ));
    }, [setChats]);

    // Logic: Set Chat Category
    const setChatCategory = useCallback((chatId, category) => {
        setChats(prev => prev.map(chat =>
            chat.id === chatId ? { ...chat, category } : chat
        ));
    }, [setChats]);

    // Logic: Pin/Unpin Message
    const pinMessage = useCallback((chatId, messageId, isPinned = true) => {
        setChats(prev => prev.map(chat => {
            if (chat.id !== chatId) return chat;
            const pinnedMessages = chat.pinnedMessages || [];
            if (isPinned && !pinnedMessages.includes(messageId)) {
                return { ...chat, pinnedMessages: [...pinnedMessages, messageId] };
            } else if (!isPinned) {
                return { ...chat, pinnedMessages: pinnedMessages.filter(id => id !== messageId) };
            }
            return chat;
        }));
    }, [setChats]);

    // Logic: Vote on Poll
    const votePoll = useCallback((chatId, pollId, optionId) => {
        setChats(prev => prev.map(chat => {
            if (chat.id !== chatId) return chat;
            const polls = chat.polls || [];
            const pollIndex = polls.findIndex(p => p.id === pollId);
            if (pollIndex === -1) return chat;

            const poll = { ...polls[pollIndex] };
            const userId = 'user-me';

            if (poll.isMultiChoice) {
                const newOptions = poll.options.map(opt => {
                    if (opt.id === optionId) {
                        const votes = opt.votes || [];
                        if (votes.includes(userId)) {
                            return { ...opt, votes: votes.filter(id => id !== userId) };
                        } else {
                            return { ...opt, votes: [...votes, userId] };
                        }
                    }
                    return opt;
                });
                poll.options = newOptions;

            } else {
                const newOptions = poll.options.map(opt => {
                    const votes = opt.votes || [];
                    if (opt.id === optionId) {
                        if (!votes.includes(userId)) {
                            return { ...opt, votes: [...votes, userId] };
                        }
                        return opt;
                    } else {
                        return { ...opt, votes: votes.filter(id => id !== userId) };
                    }
                });
                poll.options = newOptions;
            }

            const newPolls = [...polls];
            newPolls[pollIndex] = poll;
            return { ...chat, polls: newPolls };
        }));
    }, [setChats]);

    const value = {
        sendMessage,
        createChat,
        updateChat,
        deleteChat,
        deleteMessage,
        clearChatMessages,
        pinChat,
        markChatUnread,
        setChatCategory,
        pinMessage,
        votePoll
    };

    return (
        <ChatActionContext.Provider value={value}>
            {children}
        </ChatActionContext.Provider>
    );
};

