import React, { useState } from 'react';
import { MapPin, Heart, MessageCircle, MoreHorizontal, Trash2, Share2, SmilePlus } from 'lucide-react';
import { useMoments } from '../context/MomentsContext';
import { useFriend } from '../../../context/FriendContext';
import { useUser } from '../../../context/UserContext';
import { useLanguage } from '../../../context/LanguageContext';
import { cn } from '../../../utils/cn';

const REACTION_EMOJIS = ['馃槀', '鉂わ笍', '馃憤', '馃敟', '馃槷', '馃槩'];

export default function MomentCard({ post, onCommentClick }) {
    const { toggleLike, deletePost, getAuthor, addReaction } = useMoments();
    const { getDisplayName } = useFriend();
    const { userProfile, getDisplayName: getUserDisplayName } = useUser();
    const { t, language } = useLanguage();

    const [showMenu, setShowMenu] = useState(false);
    const [showReactions, setShowReactions] = useState(false);

    const author = getAuthor(post.authorId);
    const isOwn = post.authorId === 'user-me';
    const hasLiked = post.likes.includes('user-me');
    const likeCount = post.likes.length;
    const commentCount = post.comments.length;
    const reactions = post.reactions || {};

    // Get display name
    const getAuthorName = () => {
        if (isOwn) {
            return getUserDisplayName(language);
        }
        return getDisplayName(author, language);
    };

    // Get avatar
    const getAvatar = () => {
        if (isOwn) {
            return userProfile.avatar;
        }
        return author.avatar;
    };

    // Format relative time
    const formatTime = (dateStr) => {
        const date = new Date(dateStr);
        const now = new Date();
        const diffMs = now - date;
        const diffMins = Math.floor(diffMs / 60000);
        const diffHours = Math.floor(diffMs / 3600000);
        const diffDays = Math.floor(diffMs / 86400000);

        if (diffMins < 1) return t('just_now') || 'Just now';
        if (diffMins < 60) return `${diffMins} ${language === 'zh' ? '鍒嗛挓鍓? : 'min ago'}`;
        if (diffHours < 24) return `${diffHours} ${language === 'zh' ? '灏忔椂鍓? : 'h ago'}`;
        if (diffDays < 7) return `${diffDays} ${language === 'zh' ? '澶╁墠' : 'd ago'}`;
        return date.toLocaleDateString();
    };

    // Get liker names
    const getLikerNames = () => {
        if (likeCount === 0) return null;
        const names = post.likes.slice(0, 5).map(id => {
            if (id === 'user-me') return getUserDisplayName(language);
            const liker = getAuthor(id);
            return getDisplayName(liker, language);
        });
        if (likeCount > 5) {
            return names.join(', ') + ` +${likeCount - 5}`;
        }
        return names.join(', ');
    };

    // Get visible reactions
    const getReactionSummary = () => {
        const entries = Object.entries(reactions).filter(([_, users]) => users.length > 0);
        return entries.slice(0, 4); // Show max 4 different emoji types
    };

    const handleShare = () => {
        if (navigator.share) {
            navigator.share({
                title: 'Chat Buddy Moment',
                text: post.content,
            });
        } else {
            navigator.clipboard.writeText(post.content);
            alert(language === 'zh' ? '宸插鍒跺埌鍓创鏉? : 'Copied to clipboard!');
        }
    };

    const handleReaction = (emoji) => {
        addReaction(post.id, emoji, 'user-me');
        setShowReactions(false);
    };

    // Format comment with reply info
    const formatComment = (comment) => {
        const commenter = getAuthor(comment.authorId);
        const commenterName = comment.authorId === 'user-me'
            ? getUserDisplayName(language)
            : getDisplayName(commenter, language);

        if (comment.replyTo) {
            return (
                <span>
                    <span className="font-medium text-[var(--color-primary)]">{commenterName}</span>
                    <span className="text-[var(--color-text-muted)]"> {t('reply_to') || 'replied'} </span>
                    <span className="font-medium text-[var(--color-primary)]">{comment.replyTo.authorName}</span>
                    <span className="text-[var(--color-text-main)]">: {comment.content}</span>
                </span>
            );
        }

        return (
            <span>
                <span className="font-medium text-[var(--color-primary)]">{commenterName}:</span>
                <span className="text-[var(--color-text-main)] ml-1">{comment.content}</span>
            </span>
        );
    };

    return (
        <div className="bg-white border-b border-[var(--color-border-light)] px-4 py-4">
            {/* Header */}
            <div className="flex items-start gap-3">
                {/* Avatar */}
                <div className="w-10 h-10 rounded-[4px] overflow-hidden flex-shrink-0 bg-[var(--color-primary)]">
                    {getAvatar() ? (
                        <img src={getAvatar()} alt={getAuthorName()} className="w-full h-full object-cover" />
                    ) : (
                        <div className="w-full h-full flex items-center justify-center text-white font-bold">
                            {getAuthorName().charAt(0).toUpperCase()}
                        </div>
                    )}
                </div>

                {/* Content */}
                <div className="flex-1 min-w-0">
                    {/* Name and Menu */}
                    <div className="flex items-center justify-between">
                        <span className="font-medium text-[var(--color-primary)] text-[15px]">
                            {getAuthorName()}
                        </span>
                        {isOwn && (
                            <div className="relative">
                                <button
                                    onClick={() => setShowMenu(!showMenu)}
                                    className="p-1 text-[var(--color-text-muted)] hover:text-[var(--color-text-main)]"
                                >
                                    <MoreHorizontal size={18} />
                                </button>
                                {showMenu && (
                                    <>
                                        <div className="fixed inset-0 z-10" onClick={() => setShowMenu(false)} />
                                        <div className="absolute right-0 top-6 bg-white rounded-lg shadow-lg border border-[var(--color-border)] z-20 overflow-hidden">
                                            <button
                                                onClick={() => {
                                                    deletePost(post.id);
                                                    setShowMenu(false);
                                                }}
                                                className="flex items-center gap-2 px-4 py-2 text-red-500 hover:bg-red-50 whitespace-nowrap"
                                            >
                                                <Trash2 size={16} />
                                                {t('delete_post') || 'Delete'}
                                            </button>
                                        </div>
                                    </>
                                )}
                            </div>
                        )}
                    </div>

                    {/* Post Content */}
                    <p className="text-[var(--color-text-main)] text-[15px] mt-1 whitespace-pre-wrap">
                        {post.content}
                    </p>

                    {/* Images Grid */}
                    {post.images && post.images.length > 0 && (
                        <div className={cn(
                            "grid gap-1 mt-2",
                            post.images.length === 1 && "grid-cols-1 max-w-[200px]",
                            post.images.length === 2 && "grid-cols-2 max-w-[280px]",
                            post.images.length >= 3 && "grid-cols-3 max-w-[280px]"
                        )}>
                            {post.images.slice(0, 9).map((img, index) => (
                                <div
                                    key={index}
                                    className="aspect-square rounded overflow-hidden bg-[var(--color-bg-app)]"
                                >
                                    <img src={img} alt="" className="w-full h-full object-cover" />
                                </div>
                            ))}
                        </div>
                    )}

                    {/* Location */}
                    {post.location && (
                        <div className="flex items-center gap-1 mt-2 text-[var(--color-text-muted)] text-[12px]">
                            <MapPin size={12} />
                            <span>{post.location}</span>
                        </div>
                    )}

                    {/* Time and Actions */}
                    <div className="flex items-center justify-between mt-3">
                        <span className="text-[var(--color-text-muted)] text-[12px]">
                            {formatTime(post.createdAt)}
                        </span>

                        <div className="flex items-center gap-4">
                            {/* Reaction Picker */}
                            <div className="relative">
                                <button
                                    onClick={() => setShowReactions(!showReactions)}
                                    className="text-[var(--color-text-muted)] hover:text-[var(--color-primary)] transition-colors"
                                >
                                    <SmilePlus size={16} />
                                </button>
                                {showReactions && (
                                    <>
                                        <div className="fixed inset-0 z-10" onClick={() => setShowReactions(false)} />
                                        <div className="absolute bottom-6 right-0 bg-white rounded-full shadow-lg border border-[var(--color-border)] z-20 flex gap-1 p-1">
                                            {REACTION_EMOJIS.map(emoji => (
                                                <button
                                                    key={emoji}
                                                    onClick={() => handleReaction(emoji)}
                                                    className="w-8 h-8 flex items-center justify-center hover:bg-[var(--color-bg-app)] rounded-full text-[18px] transition-transform hover:scale-125"
                                                >
                                                    {emoji}
                                                </button>
                                            ))}
                                        </div>
                                    </>
                                )}
                            </div>

                            {/* Share */}
                            <button
                                onClick={handleShare}
                                className="text-[var(--color-text-muted)] hover:text-[var(--color-primary)] transition-colors"
                            >
                                <Share2 size={16} />
                            </button>

                            {/* Comment */}
                            <button
                                onClick={() => onCommentClick(post)}
                                className="flex items-center gap-1 text-[var(--color-text-muted)] hover:text-[var(--color-primary)] transition-colors"
                            >
                                <MessageCircle size={16} />
                                {commentCount > 0 && <span className="text-[12px]">{commentCount}</span>}
                            </button>

                            {/* Like */}
                            <button
                                onClick={() => toggleLike(post.id)}
                                className={cn(
                                    "flex items-center gap-1 transition-colors",
                                    hasLiked ? "text-red-500" : "text-[var(--color-text-muted)] hover:text-red-500"
                                )}
                            >
                                <Heart size={16} className={hasLiked ? "fill-current" : ""} />
                                {likeCount > 0 && <span className="text-[12px]">{likeCount}</span>}
                            </button>
                        </div>
                    </div>

                    {/* Reactions Display */}
                    {getReactionSummary().length > 0 && (
                        <div className="flex items-center gap-1 mt-2 flex-wrap">
                            {getReactionSummary().map(([emoji, users]) => (
                                <div
                                    key={emoji}
                                    className="flex items-center bg-[var(--color-bg-app)] rounded-full px-2 py-0.5 text-[12px]"
                                >
                                    <span>{emoji}</span>
                                    <span className="ml-1 text-[var(--color-text-muted)]">{users.length}</span>
                                </div>
                            ))}
                        </div>
                    )}

                    {/* Likes and Comments Section */}
                    {(likeCount > 0 || commentCount > 0) && (
                        <div className="mt-2 bg-[var(--color-bg-app)] rounded-lg overflow-hidden">
                            {/* Likes */}
                            {likeCount > 0 && (
                                <div className="px-2 py-1.5 flex items-start gap-1 border-b border-[var(--color-border-light)]">
                                    <Heart size={14} className="text-red-500 fill-red-500 flex-shrink-0 mt-0.5" />
                                    <span className="text-[13px] text-[var(--color-text-main)]">
                                        {getLikerNames()}
                                    </span>
                                </div>
                            )}

                            {/* Recent Comments */}
                            {commentCount > 0 && (
                                <div className="px-2 py-1.5">
                                    {post.comments.slice(-3).map((comment) => (
                                        <div key={comment.id} className="text-[13px] py-0.5">
                                            {formatComment(comment)}
                                        </div>
                                    ))}
                                    {commentCount > 3 && (
                                        <button
                                            onClick={() => onCommentClick(post)}
                                            className="text-[12px] text-[var(--color-primary)] mt-1"
                                        >
                                            {t('view_all_comments') || `View all ${commentCount} comments`}
                                        </button>
                                    )}
                                </div>
                            )}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

import React, { createContext, useContext, useCallback } from 'react';
import { INITIAL_PERSONAS } from '../../../data/personas';
import {
    callMomentsAI,
    getTimeContext,
    getRandomLocation,
    evaluateInterestMatch,
    generatePostSystemPrompt,
    generateCommentSystemPrompt
} from '../services/momentsService';

const MomentsActionContext = createContext();

export const useMomentsActions = () => {
    const context = useContext(MomentsActionContext);
    if (!context) throw new Error('useMomentsActions must be used within a MomentsProvider');
    return context;
};

export const MomentsActionProvider = ({ children, setMomentsData, momentsData }) => {
    // We need to read current posts from momentsData prop or ref?
    // Using functional state updates is safer for simple things, but for AI logic that needs to read *other* data, 
    // we might need the latest state. 
    // In ChatContext we used Refs. Here we can use the prop `momentsData` but be careful about staleness in closures.
    // Ideally we pass a Ref for reading latest state in async ops.
    // Let's assume the parent passes a `momentsDataRef`.

    // Actually, let's use the functional updates where possible.

    // ========== CRUD ACTIONS ==========

    const createPost = useCallback((content, images = [], video = null, authorId = 'user-me', options = {}) => {
        const {
            location = null,
            visibility = 'public',
            visibleTo = null,
            hiddenFrom = null
        } = options;

        const newPost = {
            id: `post-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
            authorId,
            content,
            images,
            video,
            location,
            visibility,
            visibleTo,
            hiddenFrom,
            createdAt: new Date().toISOString(),
            likes: [],
            comments: [],
            reactions: {}
        };

        setMomentsData(prev => ({
            ...prev,
            posts: [newPost, ...(prev.posts || [])]
        }));

        // AI Hook will detect this and trigger interactions if needed
        return newPost.id;
    }, [setMomentsData]);

    const deletePost = useCallback((postId) => {
        setMomentsData(prev => ({
            ...prev,
            posts: (prev.posts || []).filter(p => p.id !== postId)
        }));
    }, [setMomentsData]);

    const toggleLike = useCallback((postId, userId = 'user-me') => {
        setMomentsData(prev => ({
            ...prev,
            posts: (prev.posts || []).map(post => {
                if (post.id !== postId) return post;
                const hasLiked = post.likes.includes(userId);
                return {
                    ...post,
                    likes: hasLiked
                        ? post.likes.filter(id => id !== userId)
                        : [...post.likes, userId]
                };
            })
        }));
    }, [setMomentsData]);

    const addReaction = useCallback((postId, emoji, userId = 'user-me') => {
        setMomentsData(prev => ({
            ...prev,
            posts: (prev.posts || []).map(post => {
                if (post.id !== postId) return post;
                const reactions = { ...post.reactions };
                if (!reactions[emoji]) reactions[emoji] = [];
                if (!reactions[emoji].includes(userId)) {
                    reactions[emoji] = [...reactions[emoji], userId];
                }
                return { ...post, reactions };
            })
        }));
    }, [setMomentsData]);

    const addComment = useCallback((postId, content, authorId = 'user-me', replyTo = null) => {
        const newComment = {
            id: `cmt-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
            authorId,
            content,
            createdAt: new Date().toISOString(),
            replyTo
        };

        setMomentsData(prev => ({
            ...prev,
            posts: (prev.posts || []).map(post => {
                if (post.id !== postId) return post;
                return {
                    ...post,
                    comments: [...post.comments, newComment]
                };
            })
        }));
        return newComment.id;
    }, [setMomentsData]);

    const deleteComment = useCallback((postId, commentId) => {
        setMomentsData(prev => ({
            ...prev,
            posts: (prev.posts || []).map(post => {
                if (post.id !== postId) return post;
                return {
                    ...post,
                    comments: post.comments.filter(c => c.id !== commentId)
                };
            })
        }));
    }, [setMomentsData]);

    const setImageApiConfig = useCallback((apiKey, apiUrl) => {
        setMomentsData(prev => ({
            ...prev,
            imageApiKey: apiKey,
            imageApiUrl: apiUrl
        }));
    }, [setMomentsData]);

    // ========== AI ACTIONS ==========

    const generateDynamicAIPost = useCallback(async (aiId) => {
        const persona = INITIAL_PERSONAS.find(p => p.id === aiId);
        if (!persona) return false;

        const timeContext = getTimeContext();
        const randomLocation = getRandomLocation(aiId);
        const systemPrompt = generatePostSystemPrompt(persona, timeContext, randomLocation);

        const response = await callMomentsAI([
            { role: 'system', content: systemPrompt },
            { role: 'user', content: 'Generate a post.' }
        ], 150);

        if (response) {
            createPost(response, [], null, aiId, { location: randomLocation });
            setMomentsData(prev => ({
                ...prev,
                lastAIPostTime: {
                    ...prev.lastAIPostTime,
                    [aiId]: Date.now()
                }
            }));
            console.log(`[MomentsAI] ${persona.name} posted: ${response.substring(0, 50)}...`);
            return true;
        }
        return false;
    }, [createPost, setMomentsData]);

    const generateAIComment = useCallback(async (postId, aiId, replyToComment = null, postsSnapshot) => {
        // We need a snapshot of posts to read content. 
        // passing `postsSnapshot` as arg allows caller (hook) to provide latest state.

        const post = postsSnapshot.find(p => p.id === postId);
        if (!post) return null;

        const persona = INITIAL_PERSONAS.find(p => p.id === aiId);
        if (!persona) return null;

        const getAuthorName = (id) => {
            if (id === 'user-me') return 'You';
            return INITIAL_PERSONAS.find(p => p.id === id)?.name || 'Unknown';
        };

        const postAuthorName = getAuthorName(post.authorId);
        const existingComments = post.comments.slice(-5).map(c => {
            const authorName = getAuthorName(c.authorId);
            return `${authorName}: ${c.content}`;
        }).join('\n');

        const systemPrompt = generateCommentSystemPrompt(persona, postAuthorName, post.content, existingComments, replyToComment);

        const response = await callMomentsAI([
            { role: 'system', content: systemPrompt },
            { role: 'user', content: 'Write your comment.' }
        ], 80);

        if (response) {
            const replyData = replyToComment ? {
                commentId: replyToComment.commentId,
                authorId: replyToComment.authorId,
                authorName: replyToComment.authorName
            } : null;

            addComment(postId, response, aiId, replyData);
            console.log(`[MomentsAI] ${persona.name} commented: ${response}`);
            return response;
        }
        return null;
    }, [addComment]);

    // Export values
    const value = {
        createPost,
        deletePost,
        toggleLike,
        addReaction,
        addComment,
        deleteComment,
        setImageApiConfig,
        generateDynamicAIPost,
        generateAIComment
    };

    return (
        <MomentsActionContext.Provider value={value}>
            {children}
        </MomentsActionContext.Provider>
    );
};

import React, { createContext, useContext, useEffect, useRef, useCallback } from 'react';
import { INITIAL_PERSONAS } from '../../../data/personas';
import { MomentsStateProvider, useMomentsState } from './MomentsState';
import { MomentsActionProvider, useMomentsActions } from './MomentsActions';
import { evaluateInterestMatch } from '../services/momentsService';

const MomentsContext = createContext();

// Facade Hook
export const useMoments = () => {
    const state = useMomentsState();
    const actions = useMomentsActions();

    // Selectors / Helpers
    const getAuthor = useCallback((authorId) => {
        if (authorId === 'user-me') {
            return { id: 'user-me', name: 'You', name_zh: '鎴?, avatar: null };
        }
        return INITIAL_PERSONAS.find(p => p.id === authorId) || { id: authorId, name: 'Unknown', avatar: null };
    }, []);

    const getImageApiConfig = useCallback(() => {
        return {
            apiKey: state.imageApiKey || '',
            apiUrl: state.imageApiUrl || ''
        };
    }, [state.imageApiKey, state.imageApiUrl]);

    const getAIAccessibleContent = useCallback((aiId) => {
        const posts = state.posts || [];
        // Get AI's own posts
        const ownPosts = posts.filter(p => p.authorId === aiId).slice(0, 5);
        // Get posts AI has interacted with
        const interactedPosts = posts.filter(p =>
            p.likes.includes(aiId) ||
            p.comments.some(c => c.authorId === aiId)
        ).slice(0, 5);
        // Get recent user posts
        const userPosts = posts.filter(p => p.authorId === 'user-me').slice(0, 3);

        return {
            ownPosts,
            interactedPosts,
            userPosts,
            summary: `${ownPosts.length} own posts, ${interactedPosts.length} interactions, ${userPosts.length} user posts`
        };
    }, [state.posts]);

    return {
        ...state,
        ...actions,
        getAuthor,
        getImageApiConfig,
        getAIAccessibleContent
    };
};

export const MomentsProvider = ({ children }) => {
    return (
        <MomentsStateProvider>
            <InternalMomentsProvider>
                {children}
            </InternalMomentsProvider>
        </MomentsStateProvider>
    );
};

// Internal provider to access state/actions for AI Hook
const InternalMomentsProvider = ({ children }) => {
    const { momentsData, setMomentsData } = useMomentsState();

    return (
        <MomentsActionProvider momentsData={momentsData} setMomentsData={setMomentsData}>
            <MomentsAIOrchestrator />
            {children}
        </MomentsActionProvider>
    );
};

// Component to run AI hooks (needs access to both State and Actions)
const MomentsAIOrchestrator = () => {
    const { posts, lastAIPostTime } = useMomentsState();
    const { generateDynamicAIPost, generateAIComment, toggleLike, addReaction } = useMomentsActions();

    useMomentsAI({
        posts,
        lastAIPostTime,
        generateDynamicAIPost,
        generateAIComment,
        toggleLike,
        addReaction
    });

    return null;
};

// -----------------------------------------------------------------------------
// AI ORCHESTRATION HOOK
// -----------------------------------------------------------------------------
function useMomentsAI({ posts, lastAIPostTime, generateDynamicAIPost, generateAIComment, toggleLike, addReaction }) {

    const aiPostIntervalRef = useRef(null);
    const aiInteractionIntervalRef = useRef(null);
    const processedPostIdsRef = useRef(new Set());

    // Evaluate if AI should like a post
    const evaluateShouldLike = useCallback((post, aiId) => {
        const persona = INITIAL_PERSONAS.find(p => p.id === aiId);
        if (!persona) return false;

        // High chance for user posts
        if (post.authorId === 'user-me') return Math.random() > 0.3;

        // Check interests
        if (evaluateInterestMatch(post.content, persona.interests)) {
            return Math.random() > 0.2;
        }
        return Math.random() > 0.6;
    }, []);

    // Trigger AI interactions on a specific post
    const triggerAIInteractions = useCallback(async (postId, currentPosts) => {
        const post = currentPosts.find(p => p.id === postId);
        if (!post) return;

        const shuffledPersonas = [...INITIAL_PERSONAS].sort(() => Math.random() - 0.5);
        const interactors = shuffledPersonas.slice(0, 3 + Math.floor(Math.random() * 4));

        for (let i = 0; i < interactors.length; i++) {
            const persona = interactors[i];
            const delay = (i + 1) * (2000 + Math.random() * 4000);

            setTimeout(async () => {
                // Like
                if (evaluateShouldLike(post, persona.id)) {
                    toggleLike(postId, persona.id);
                }
                // React
                if (Math.random() > 0.7) {
                    const emojis = ['馃槀', '鉂わ笍', '馃憤', '馃敟', '馃槷', '馃槩'];
                    const emoji = emojis[Math.floor(Math.random() * emojis.length)];
                    addReaction(postId, emoji, persona.id);
                }
                // Comment
                if (Math.random() > 0.6) {
                    // Need fresh posts snapshot for comment generation? 
                    // `generateAIComment` uses `callMomentsAI`.
                    // We need to pass the *current* posts to `generateAIComment`?
                    // In `MomentsActions`, `generateAIComment` accepts a snapshot. 
                    // But here we rely on the closure `posts` or we need access to fresh `posts` via ref?
                    // The hook re-runs when `posts` changes, so `triggerAIInteractions` is recreated.
                    // But `setTimeout` closure might capture OLD `triggerAIInteractions` scope...
                    // Wait, `triggerAIInteractions` is called with `currentPosts`.
                    // But `generateAIComment` implementation in Actions (which I defined in prev step) 
                    // assumed it will be passed a snapshot OR uses state? 
                    // In my previous step, I defined `generateAIComment` to take `postsSnapshot`.

                    // Wait, looking at `MomentsActions.jsx` I wrote:
                    // `const generateAIComment = useCallback(async (postId, aiId, replyToComment = null, postsSnapshot) => { ...`
                    // So I MUST pass `posts` (which is passed to this hook) to it.

                    // The issue is `posts` inside `setTimeout` will be STALE.
                    // I need a ref to posts.

                    // But `triggerAIInteractions` is only called from effects where we pass explicit post list or
                    // we use a Ref.

                    // Actually, let's keep it simple. It's okay if it's slightly stale for comments context,
                    // or I should maintain a `postsRef`.

                    // For now, assume `generateAIComment` handles it or I pass the `post` object directly?
                    // `generateAIComment` finds the post by ID from `postsSnapshot`.

                    // Let's use a ref for posts in this hook.

                }
            }, delay);
        }
    }, [evaluateShouldLike, toggleLike, addReaction]); // Missing `posts` dependency usually, but we handle it via Ref

    const postsRef = useRef(posts);
    useEffect(() => { postsRef.current = posts; }, [posts]);

    const triggerAIInteractionsWithRef = useCallback((postId) => {
        const currentPosts = postsRef.current;
        const post = currentPosts.find(p => p.id === postId);
        if (!post) return;

        const shuffledPersonas = [...INITIAL_PERSONAS].sort(() => Math.random() - 0.5);
        const interactors = shuffledPersonas.slice(0, 3 + Math.floor(Math.random() * 4));

        interactors.forEach((persona, i) => {
            const delay = (i + 1) * (2000 + Math.random() * 4000);
            setTimeout(async () => {
                if (evaluateShouldLike(post, persona.id)) {
                    toggleLike(postId, persona.id);
                }
                if (Math.random() > 0.7) {
                    const emojis = ['馃槀', '鉂わ笍', '馃憤', '馃敟', '馃槷', '馃槩'];
                    const emoji = emojis[Math.floor(Math.random() * emojis.length)];
                    addReaction(postId, emoji, persona.id);
                }
                if (Math.random() > 0.6) {
                    await generateAIComment(postId, persona.id, null, postsRef.current);
                }
            }, delay);
        });
    }, [evaluateShouldLike, toggleLike, addReaction, generateAIComment]);

    // Effect: Detect new user posts
    useEffect(() => {
        if (!posts.length) return;
        const latestPost = posts[0]; // Assuming NEWEST first

        if (latestPost.authorId === 'user-me' && !processedPostIdsRef.current.has(latestPost.id)) {
            // It's a new user post!
            processedPostIdsRef.current.add(latestPost.id);
            setTimeout(() => triggerAIInteractionsWithRef(latestPost.id), 2000 + Math.random() * 5000);
        }
    }, [posts, triggerAIInteractionsWithRef]);

    // Periodic AI Posts
    const checkAIPosts = useCallback(async () => {
        const now = Date.now();
        const MIN_INTERVAL = 30 * 60 * 1000;
        const MAX_INTERVAL = 2 * 60 * 60 * 1000;

        for (const persona of INITIAL_PERSONAS) {
            const lastPost = lastAIPostTime[persona.id] || 0;
            const interval = MIN_INTERVAL + Math.random() * (MAX_INTERVAL - MIN_INTERVAL);

            if (now - lastPost > interval) {
                if (Math.random() > 0.85) {
                    await generateDynamicAIPost(persona.id);
                    break;
                }
            }
        }
    }, [lastAIPostTime, generateDynamicAIPost]);

    // Periodic Mutual Interactions
    const triggerAIMutualInteraction = useCallback(async () => {
        const currentPosts = postsRef.current;
        const recentAIPosts = currentPosts
            .filter(p => p.authorId !== 'user-me' && p.authorId.startsWith('ai-'))
            .slice(0, 10);

        if (recentAIPosts.length === 0) return;

        const randomPost = recentAIPosts[Math.floor(Math.random() * recentAIPosts.length)];
        const otherAIs = INITIAL_PERSONAS.filter(p => p.id !== randomPost.authorId);

        if (otherAIs.length > 0 && Math.random() > 0.7) {
            const randomAI = otherAIs[Math.floor(Math.random() * otherAIs.length)];
            const hasLiked = randomPost.likes.includes(randomAI.id);
            const hasCommented = randomPost.comments.some(c => c.authorId === randomAI.id);

            if (!hasLiked && !hasCommented) {
                if (Math.random() > 0.4) {
                    toggleLike(randomPost.id, randomAI.id);
                }
                if (Math.random() > 0.6) {
                    await generateAIComment(randomPost.id, randomAI.id, null, currentPosts);
                }
            }
        }
    }, [toggleLike, generateAIComment]);

    // Intervals
    useEffect(() => {
        aiPostIntervalRef.current = setInterval(checkAIPosts, 10 * 60 * 1000);
        aiInteractionIntervalRef.current = setInterval(triggerAIMutualInteraction, 15 * 60 * 1000);

        return () => {
            clearInterval(aiPostIntervalRef.current);
            clearInterval(aiInteractionIntervalRef.current);
        };
    }, [checkAIPosts, triggerAIMutualInteraction]);

    // Init AI posts if empty
    useEffect(() => {
        if (posts.length === 0) {
            const initialAIs = [...INITIAL_PERSONAS].sort(() => Math.random() - 0.5).slice(0, 4);
            initialAIs.forEach((persona, index) => {
                setTimeout(() => generateDynamicAIPost(persona.id), index * 2000);
            });
        }
    }, []); // Run once 
}

import React, { createContext, useContext, useRef } from 'react';
import { useLocalStorage } from '../../../hooks/useLocalStorage';

const MomentsStateContext = createContext();

const DEFAULT_MOMENTS_DATA = {
    posts: [],
    lastAIPostTime: {},
    imageApiKey: '',
    imageApiUrl: '',
};

export const useMomentsState = () => {
    const context = useContext(MomentsStateContext);
    if (!context) throw new Error('useMomentsState must be used within a MomentsProvider');
    return context;
};

export const MomentsStateProvider = ({ children }) => {
    const [momentsData, setMomentsData] = useLocalStorage('chat-buddy-moments', DEFAULT_MOMENTS_DATA);

    // Refs for intervals (moved here or staying in provider? If logic is extracted, refs might be needed in the logic hook)
    // Actually, the main provider (Facade) will hold the AI logic which uses these refs.
    // But the refs themselves are not really "State" that consumers need.
    // Consumers just need `posts` etc.

    // We will expose setters here so ActionProvider can use them.

    const value = {
        momentsData,
        setMomentsData,
        posts: momentsData.posts || [],
        lastAIPostTime: momentsData.lastAIPostTime || {},
        imageApiKey: momentsData.imageApiKey,
        imageApiUrl: momentsData.imageApiUrl
    };

    return (
        <MomentsStateContext.Provider value={value}>
            {children}
        </MomentsStateContext.Provider>
    );
};

import { useState, useEffect } from 'react';

export function useLocalStorage(key, initialValue) {
    // Get from local storage then use state
    const [storedValue, setStoredValue] = useState(() => {
        try {
            const item = window.localStorage.getItem(key);
            return item ? JSON.parse(item) : initialValue;
        } catch (error) {
            console.error(error);
            return initialValue;
        }
    });

    // Return a wrapped version of useState's setter function that ...
    // ... persists the new value to localStorage.
    const setValue = (value) => {
        try {
            // Allow value to be a function so we have same API as useState
            setStoredValue(current => {
                const valueToStore = value instanceof Function ? value(current) : value;
                // Save to local storage
                window.localStorage.setItem(key, JSON.stringify(valueToStore));
                return valueToStore;
            });
        } catch (error) {
            console.error(error);
        }
    };

    return [storedValue, setValue];
}

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, Star, Users, ChevronRight, Settings } from 'lucide-react';
import { useChat } from '../features/chat/context/ChatContext';
import { useFriend } from '../context/FriendContext';
import { useLanguage } from '../context/LanguageContext';
import FriendDetail from '../components/FriendDetail';
import { cn } from '../utils/cn';

export default function FriendsPage() {
    const navigate = useNavigate();
    const { personas } = useChat();
    const { groups, getFriendMeta, getDisplayName, getStarredFriends, getFriendsInGroup, getUngroupedFriends } = useFriend();
    const { t, language } = useLanguage();

    const [searchTerm, setSearchTerm] = useState('');
    const [activeFilter, setActiveFilter] = useState('all'); // 'all', 'starred', or group id
    const [selectedFriend, setSelectedFriend] = useState(null);

    // Filter friends based on search and active filter
    const getFilteredFriends = () => {
        let filtered = personas;

        // Apply search filter
        if (searchTerm) {
            filtered = filtered.filter(p => {
                const displayName = getDisplayName(p, language);
                const originalName = language === 'zh' ? (p.name_zh || p.name) : p.name;
                return displayName.toLowerCase().includes(searchTerm.toLowerCase()) ||
                    originalName.toLowerCase().includes(searchTerm.toLowerCase());
            });
        }

        // Apply category filter
        if (activeFilter === 'starred') {
            filtered = getStarredFriends(filtered);
        } else if (activeFilter !== 'all') {
            filtered = getFriendsInGroup(activeFilter, filtered);
        }

        // Sort: starred first, then alphabetically
        return filtered.sort((a, b) => {
            const aMeta = getFriendMeta(a.id);
            const bMeta = getFriendMeta(b.id);
            if (aMeta.starred && !bMeta.starred) return -1;
            if (!aMeta.starred && bMeta.starred) return 1;
            return getDisplayName(a, language).localeCompare(getDisplayName(b, language));
        });
    };

    const filteredFriends = getFilteredFriends();
    const starredCount = getStarredFriends(personas).length;

    return (
        <div className="flex-1 h-full bg-[var(--color-bg-app)] overflow-hidden flex flex-col pb-16 md:pb-0">
            {/* Header */}
            <div className="bg-white px-4 py-3 flex items-center justify-between border-b border-[var(--color-border)]">
                <h1 className="text-[17px] font-medium text-[var(--color-text-main)]">
                    {t('friends') || 'Friends'}
                </h1>
                <button
                    onClick={() => navigate('/friends/groups')}
                    className="text-[var(--color-primary)]"
                >
                    <Settings size={22} />
                </button>
            </div>

            {/* Search */}
            <div className="p-2 bg-[var(--color-bg-app)]">
                <div className="relative">
                    <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 text-[#B2B2B2]" size={14} />
                    <input
                        type="text"
                        placeholder={t('search') || 'Search'}
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="w-full bg-white border-none rounded py-1.5 pl-8 pr-3 text-sm placeholder:text-[#B2B2B2] focus:outline-none"
                    />
                </div>
            </div>

            {/* Filter Tabs */}
            <div className="bg-white px-2 py-2 flex gap-2 overflow-x-auto border-b border-[var(--color-border)]">
                <FilterTab
                    active={activeFilter === 'all'}
                    onClick={() => setActiveFilter('all')}
                    label={t('all_friends') || 'All'}
                    count={personas.length}
                />
                <FilterTab
                    active={activeFilter === 'starred'}
                    onClick={() => setActiveFilter('starred')}
                    label={<><Star size={14} className="inline mr-1" />{t('starred_friends') || 'Starred'}</>}
                    count={starredCount}
                    highlight
                />
                {groups.map(group => (
                    <FilterTab
                        key={group.id}
                        active={activeFilter === group.id}
                        onClick={() => setActiveFilter(group.id)}
                        label={<><span className="mr-1">{group.icon}</span>{language === 'zh' ? group.name : group.name_en}</>}
                        count={getFriendsInGroup(group.id, personas).length}
                        color={group.color}
                    />
                ))}
            </div>

            {/* Friend List */}
            <div className="flex-1 overflow-y-auto bg-white">
                {filteredFriends.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-16 text-[var(--color-text-muted)]">
                        <Users size={48} className="mb-4 opacity-50" />
                        <p>{t('no_friends_found') || 'No friends found'}</p>
                    </div>
                ) : (
                    filteredFriends.map((friend) => {
                        const meta = getFriendMeta(friend.id);
                        const displayName = getDisplayName(friend, language);
                        const originalName = language === 'zh' ? (friend.name_zh || friend.name) : friend.name;
                        const friendGroup = groups.find(g => g.id === meta.groupId);

                        return (
                            <div
                                key={friend.id}
                                onClick={() => setSelectedFriend(friend)}
                                className="flex items-center px-4 py-3 border-b border-[var(--color-border-light)] active:bg-[#ECECEC] cursor-pointer"
                            >
                                {/* Avatar */}
                                <div className="w-11 h-11 rounded-[4px] overflow-hidden flex-shrink-0 bg-[#E0E0E0] mr-3">
                                    <img src={friend.avatar} alt={displayName} className="w-full h-full object-cover" />
                                </div>

                                {/* Name and Info */}
                                <div className="flex-1 min-w-0">
                                    <div className="flex items-center gap-2">
                                        <span className="text-[16px] text-[var(--color-text-main)] truncate">
                                            {displayName}
                                        </span>
                                        {meta.starred && (
                                            <Star size={14} className="text-yellow-500 fill-yellow-500 flex-shrink-0" />
                                        )}
                                    </div>
                                    <div className="flex items-center gap-2 mt-0.5">
                                        {meta.remark && displayName !== originalName && (
                                            <span className="text-[12px] text-[var(--color-text-muted)]">
                                                ({originalName})
                                            </span>
                                        )}
                                        {friendGroup && (
                                            <span
                                                className="text-[11px] px-1.5 py-0.5 rounded-full"
                                                style={{ backgroundColor: friendGroup.color + '20', color: friendGroup.color }}
                                            >
                                                {friendGroup.icon} {language === 'zh' ? friendGroup.name : friendGroup.name_en}
                                            </span>
                                        )}
                                    </div>
                                </div>

                                <ChevronRight size={20} className="text-[#C7C7CC] flex-shrink-0" />
                            </div>
                        );
                    })
                )}
            </div>

            {/* Friend Detail Modal */}
            {selectedFriend && (
                <FriendDetail
                    friend={selectedFriend}
                    onClose={() => setSelectedFriend(null)}
                />
            )}
        </div>
    );
}

function FilterTab({ active, onClick, label, count, highlight, color }) {
    return (
        <button
            onClick={onClick}
            className={cn(
                "px-3 py-1.5 rounded-full text-[13px] font-medium whitespace-nowrap flex items-center gap-1 transition-all",
                active
                    ? "bg-[var(--color-primary)] text-white"
                    : highlight
                        ? "bg-yellow-100 text-yellow-700"
                        : color
                            ? "bg-opacity-20 text-[var(--color-text-main)]"
                            : "bg-[var(--color-bg-app)] text-[var(--color-text-muted)]"
            )}
            style={!active && color ? { backgroundColor: color + '20', color: color } : {}}
        >
            {label}
            {count !== undefined && (
                <span className={cn(
                    "text-[11px] px-1.5 py-0.5 rounded-full",
                    active ? "bg-white/20 text-white" : "bg-black/5"
                )}>
                    {count}
                </span>
            )}
        </button>
    );
}

