/**
 * File utilities for handling file uploads and processing
 */

// Supported file types and their MIME types
export const SUPPORTED_FILE_TYPES = {
    'txt': { mime: 'text/plain', icon: '馃搫', category: 'text' },
    'md': { mime: 'text/markdown', icon: '馃摑', category: 'text' },
    'json': { mime: 'application/json', icon: '馃搵', category: 'code' },
    'js': { mime: 'application/javascript', icon: '鈿?, category: 'code' },
    'ts': { mime: 'application/typescript', icon: '馃敺', category: 'code' },
    'py': { mime: 'text/x-python', icon: '馃悕', category: 'code' },
    'html': { mime: 'text/html', icon: '馃寪', category: 'code' },
    'css': { mime: 'text/css', icon: '馃帹', category: 'code' },
    'xml': { mime: 'application/xml', icon: '馃摪', category: 'code' },
    'csv': { mime: 'text/csv', icon: '馃搳', category: 'data' },
    'yaml': { mime: 'text/yaml', icon: '馃搼', category: 'config' },
    'yml': { mime: 'text/yaml', icon: '馃搼', category: 'config' }
};

// Maximum file size (5MB)
export const MAX_FILE_SIZE = 5 * 1024 * 1024;

/**
 * Get file extension from filename
 */
export function getFileExtension(filename) {
    return filename.split('.').pop()?.toLowerCase() || '';
}

/**
 * Check if file type is supported
 */
export function isFileTypeSupported(filename) {
    const ext = getFileExtension(filename);
    return ext in SUPPORTED_FILE_TYPES;
}

/**
 * Get file type info
 */
export function getFileTypeInfo(filename) {
    const ext = getFileExtension(filename);
    return SUPPORTED_FILE_TYPES[ext] || { mime: 'application/octet-stream', icon: '馃搸', category: 'unknown' };
}

/**
 * Format file size for display
 */
export function formatFileSize(bytes) {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / (1024 * 1024)).toFixed(2) + ' MB';
}

/**
 * Read file as text
 */
export function readFileAsText(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => resolve(e.target.result);
        reader.onerror = reject;
        reader.readAsText(file);
    });
}

/**
 * Read file as base64
 */
export function readFileAsBase64(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => resolve(e.target.result);
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
}

/**
 * Validate file for upload
 */
export function validateFile(file) {
    const errors = [];

    if (file.size > MAX_FILE_SIZE) {
        errors.push('file_too_large');
    }

    if (!isFileTypeSupported(file.name)) {
        errors.push('unsupported_file_type');
    }

    return {
        valid: errors.length === 0,
        errors
    };
}

/**
 * Process file for chat
 * Returns file data object for storing in message
 */
export async function processFileForChat(file) {
    const validation = validateFile(file);
    if (!validation.valid) {
        throw new Error(validation.errors[0]);
    }

    const content = await readFileAsText(file);
    const typeInfo = getFileTypeInfo(file.name);

    return {
        name: file.name,
        size: file.size,
        type: getFileExtension(file.name),
        icon: typeInfo.icon,
        category: typeInfo.category,
        content: content,
        uploadedAt: new Date().toISOString()
    };
}

/**
 * Create a downloadable file from content
 */
export function downloadFile(filename, content, mimeType = 'text/plain') {
    const blob = new Blob([content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
}

/**
 * Extract text content for RAG indexing
 * Handles different file types appropriately
 */
export function extractTextContent(fileData) {
    const { content, type } = fileData;

    try {
        switch (type) {
            case 'json':
                // Pretty print JSON for better readability
                const parsed = JSON.parse(content);
                return JSON.stringify(parsed, null, 2);
            case 'csv':
                // CSV is already text
                return content;
            case 'html':
                // Strip HTML tags
                return content.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
            default:
                return content;
        }
    } catch {
        return content;
    }
}

/**
 * RAG (Retrieval Augmented Generation) utilities
 * Client-side implementation using TF-IDF keyword matching
 */

/**
 * Chunk text into smaller pieces for indexing
 * @param {string} text - Text to chunk
 * @param {number} chunkSize - Target chunk size in characters
 * @param {number} overlap - Overlap between chunks
 */
export function chunkText(text, chunkSize = 500, overlap = 100) {
    const chunks = [];
    const paragraphs = text.split(/\n\n+/);
    let currentChunk = '';

    for (const paragraph of paragraphs) {
        if (currentChunk.length + paragraph.length <= chunkSize) {
            currentChunk += (currentChunk ? '\n\n' : '') + paragraph;
        } else {
            if (currentChunk) {
                chunks.push(currentChunk.trim());
            }

            // Handle paragraphs longer than chunkSize
            if (paragraph.length > chunkSize) {
                const sentences = paragraph.split(/(?<=[.!?])\s+/);
                currentChunk = '';

                for (const sentence of sentences) {
                    if (currentChunk.length + sentence.length <= chunkSize) {
                        currentChunk += (currentChunk ? ' ' : '') + sentence;
                    } else {
                        if (currentChunk) {
                            chunks.push(currentChunk.trim());
                            // Add overlap from end of previous chunk
                            currentChunk = currentChunk.slice(-overlap) + ' ' + sentence;
                        } else {
                            currentChunk = sentence;
                        }
                    }
                }
            } else {
                currentChunk = paragraph;
            }
        }
    }

    if (currentChunk.trim()) {
        chunks.push(currentChunk.trim());
    }

    return chunks;
}

/**
 * Extract keywords from text using simple TF analysis
 */
export function extractKeywords(text) {
    // Common stop words to filter out
    const stopWords = new Set([
        'the', 'a', 'an', 'is', 'are', 'was', 'were', 'be', 'been', 'being',
        'have', 'has', 'had', 'do', 'does', 'did', 'will', 'would', 'could',
        'should', 'may', 'might', 'must', 'shall', 'can', 'need', 'dare',
        'ought', 'used', 'to', 'of', 'in', 'for', 'on', 'with', 'at', 'by',
        'from', 'up', 'about', 'into', 'through', 'during', 'before', 'after',
        'above', 'below', 'between', 'under', 'again', 'further', 'then',
        'once', 'here', 'there', 'when', 'where', 'why', 'how', 'all', 'each',
        'few', 'more', 'most', 'other', 'some', 'such', 'no', 'nor', 'not',
        'only', 'own', 'same', 'so', 'than', 'too', 'very', 'just', 'and',
        'but', 'if', 'or', 'because', 'as', 'until', 'while', 'although',
        'though', 'after', 'before', 'since', 'when', 'where', 'this', 'that',
        'these', 'those', 'it', 'its', 'i', 'me', 'my', 'myself', 'we', 'our',
        'ours', 'ourselves', 'you', 'your', 'yours', 'yourself', 'yourselves',
        'he', 'him', 'his', 'himself', 'she', 'her', 'hers', 'herself',
        'they', 'them', 'their', 'theirs', 'themselves', 'what', 'which',
        'who', 'whom', 'whose', '銆?, '锛?, '鐨?, '鏄?, '鍦?, '浜?, '鍜?, '涓?,
        '鎴?, '浣?, '濡傛灉', '鍥犱负', '鎵€浠?, '杩?, '閭?, '鎴?, '浣?, '浠?, '濂?, '瀹?
    ]);

    // Tokenize and normalize
    const words = text.toLowerCase()
        .replace(/[^\w\s\u4e00-\u9fff]/g, ' ')
        .split(/\s+/)
        .filter(word => word.length > 2 && !stopWords.has(word));

    // Count term frequency
    const tf = {};
    for (const word of words) {
        tf[word] = (tf[word] || 0) + 1;
    }

    // Return sorted keywords
    return Object.entries(tf)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 20)
        .map(([word]) => word);
}

/**
 * Calculate similarity between query and chunk
 * Uses term frequency overlap
 */
export function calculateSimilarity(queryKeywords, chunkKeywords) {
    const querySet = new Set(queryKeywords);
    const chunkSet = new Set(chunkKeywords);

    let matchCount = 0;
    for (const keyword of querySet) {
        if (chunkSet.has(keyword)) {
            matchCount++;
        }
    }

    // Jaccard-like similarity
    const unionSize = new Set([...querySet, ...chunkSet]).size;
    return unionSize > 0 ? matchCount / unionSize : 0;
}

/**
 * Index a document for RAG search
 */
export function indexDocument(document) {
    const { id, name, content } = document;
    const chunks = chunkText(content);

    return chunks.map((chunk, index) => ({
        documentId: id,
        documentName: name,
        chunkIndex: index,
        content: chunk,
        keywords: extractKeywords(chunk)
    }));
}

/**
 * Search indexed chunks for relevant content
 */
export function searchDocuments(query, indexedChunks, topK = 3) {
    const queryKeywords = extractKeywords(query);

    // Score each chunk
    const scoredChunks = indexedChunks.map(chunk => ({
        ...chunk,
        score: calculateSimilarity(queryKeywords, chunk.keywords)
    }));

    // Sort by score and return top K
    return scoredChunks
        .filter(chunk => chunk.score > 0)
        .sort((a, b) => b.score - a.score)
        .slice(0, topK);
}

/**
 * Build RAG context for AI prompt
 */
export function buildRAGContext(query, indexedChunks) {
    const relevantChunks = searchDocuments(query, indexedChunks);

    if (relevantChunks.length === 0) {
        return null;
    }

    const context = relevantChunks.map((chunk, index) =>
        `[Document: ${chunk.documentName}]\n${chunk.content}`
    ).join('\n\n---\n\n');

    return {
        context,
        sources: relevantChunks.map(c => ({
            documentName: c.documentName,
            documentId: c.documentId,
            chunkIndex: c.chunkIndex,
            score: c.score
        }))
    };
}

/**
 * Storage key for document index
 */
const STORAGE_KEY = 'chat-buddy-rag-index';

/**
 * Save indexed chunks to localStorage
 */
export function saveIndex(indexedChunks) {
    try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(indexedChunks));
    } catch (e) {
        console.error('Failed to save RAG index:', e);
    }
}

/**
 * Load indexed chunks from localStorage
 */
export function loadIndex() {
    try {
        const data = localStorage.getItem(STORAGE_KEY);
        return data ? JSON.parse(data) : [];
    } catch (e) {
        console.error('Failed to load RAG index:', e);
        return [];
    }
}

/**
 * Add document to index
 */
export function addDocumentToIndex(document) {
    const existingIndex = loadIndex();
    // Remove existing chunks for this document
    const filteredIndex = existingIndex.filter(c => c.documentId !== document.id);
    // Add new chunks
    const newChunks = indexDocument(document);
    const updatedIndex = [...filteredIndex, ...newChunks];
    saveIndex(updatedIndex);
    return updatedIndex;
}

/**
 * Remove document from index
 */
export function removeDocumentFromIndex(documentId) {
    const existingIndex = loadIndex();
    const updatedIndex = existingIndex.filter(c => c.documentId !== documentId);
    saveIndex(updatedIndex);
    return updatedIndex;
}
